const top_urgot = {
  champion: '우르곳',
  lane: 'top',
  patch: '26.22',
  matchups: {
    '가렌': { lv1: '가렌은 (P)\'인내심\' 덕분에 맞지 않으면 체력을 빠르게 채우니 계속해서 (Q)\'부식성 폭약\'으로 압박해야 해요. 가렌이 (Q)\'결정타\'로 달려들어 침묵을 걸려고 하면 거리를 조절하며 평타와 (Q)\'부식성 폭약\'으로 대응하세요. 1~2레벨 구간에서는 가렌이 접근하지 못하도록 거리를 유지하는 것이 중요해요.', lv3: '가렌이 (W)\'용기\'를 사용하면 보호막과 피해 감소를 얻으니 그 타이밍에는 (W)\'심판의 원\' 사격을 아꼈다가 효과가 끝난 뒤에 딜을 넣으세요. 가렌이 (Q)\'결정타\'로 들어올 때 (E)\'경멸\'을 사용해 가렌을 뒤로 던지면 흐름을 끊을 수 있어요. (E)\'심판\'에 맞으면 방어력이 감소하므로 (E)\'경멸\'의 보호막을 활용해 피해를 흡수하며 싸우세요.', lv6: '가렌의 (R)\'데마시아의 정의\'는 체력이 낮은 상태에서 매우 위협적이니 체력 관리에 신경 써야 해요. 가렌의 체력이 낮을 때 (E)\'경멸\'로 기절시킨 뒤 (R)\'불사의 공포\'를 사용하면 안전하게 처형할 수 있어요. 라인을 당겨 두어 가렌이 (R)\'데마시아의 정의\'를 쓰며 들어오는 상황에 정글러와 함께 대응하세요.', item: '굶주린 히드라를 첫 코어로 올리면 지속 교전에서 체력을 유지하며 압박하기 좋아요. 신발은 가렌의 기본 공격 피해를 줄여주는 판금 장화를 선택하세요.', spell: '점멸과 점화를 추천해요. 점화는 가렌의 (P)\'인내심\'을 통한 체력 회복을 억제하여 킬을 내기 쉽게 도와줘요.' },
    '갱플랭크': { lv1: '갱플랭크는 (Q)\'혀어어어업상\'으로 골드를 챙기며 멀리서 견제하므로 적절한 거리 조절이 필요해요. (Q)\'부식성 폭약\'을 적중시켜 갱플랭크를 둔화시킨 뒤 (W)\'심판의 원\'으로 짧은 딜교환을 시도하세요. 1~2레벨 구간에는 무리하게 맞대응하기보다 파밍에 집중하며 체력을 관리하는 것이 좋아요.', lv3: '갱플랭크가 설치한 (E)\'화약통\'의 폭발 범위에 들어가지 않도록 주의하며 (E)\'경멸\'로 진입하세요. 갱플랭크가 (W)\'괴혈병 치료\'로 군중 제어를 풀고 체력을 회복하기 전에 (Q)\'부식성 폭약\'으로 둔화를 묻히고 공격해야 해요. (E)\'경멸\'로 갱플랭크를 뒤로 넘긴 뒤에는 (W)\'심판의 원\'을 켜서 빠르게 피해를 입히세요.', lv6: '갱플랭크의 체력이 일정 수준 이하일 때 (R)\'불사의 공포\'를 사용해 처형을 노려보세요. 갱플랭크가 (R)\'포탄 세례\'를 사용해 이동 속도를 늦추려 한다면 포격 범위 밖에서 (E)\'경멸\'을 준비하며 대응하세요. 라인을 압박하며 갱플랭크가 (W)\'괴혈병 치료\'를 쓰기 전에 킬각을 잡는 것이 중요해요.', item: '굶주린 히드라를 첫 코어로 올려 공격력과 생명력 흡수를 챙기세요. 신발은 갱플랭크의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 갱플랭크의 (W)\'괴혈병 치료\' 회복량을 줄이면 (R)\'불사의 공포\'로 처형하기가 더 쉬워져요.' },
    '그라가스': { lv1: '그라가스는 (Q)\'술통 굴리기\'로 견제하고 (P)\'서비스 시간\'으로 체력을 계속 회복해요. 술통의 둔화에 걸리지 않게 주의하며, 상대가 다가왔을 때 (Q)\'부식성 폭약\'으로 둔화를 걸어 짧게 딜교환하세요. 첫 웨이브에서는 무리하게 들어가기보다 술통 위치를 확인하며 체력을 보존하세요.', lv3: '(E)\'몸통 박치기\'에 맞으면 흐름이 끊기니, 상대의 돌진기가 빠진 것을 확인한 뒤 (E)\'경멸\'로 들어가세요. (Q)\'부식성 폭약\'을 맞힌 적에게 (W)\'심판의 원\'을 사용해 화력을 집중하고, 상대의 (W)\'취중 분노\'가 켜져 있을 때는 잠시 공격을 멈춰 피해를 줄이세요. (E)\'경멸\'로 그라가스를 뒤로 던지면 (W)\'심판의 원\'을 더 오랫동안 쏟아부을 수 있어요.', lv6: '(R)\'불사의 공포\'를 맞춰 체력을 깎은 뒤 처형을 노리되, (R)\'술통 폭발\'로 밀려나지 않게 거리를 조절하세요. 그라가스의 (E)\'몸통 박치기\'에 맞으면 공중에 떠서 스킬을 쓸 수 없으니, 돌진 사거리 밖에서 기다리다가 스킬이 빠진 뒤에 진입하세요. 라인을 적당히 밀어두고 (R)\'불사의 공포\'로 압박하면 상대는 쉽게 앞으로 나오지 못해요.', item: '삼위일체를 가서 체력과 공격력을 챙기고 (W)\'심판의 원\'의 교환 효율을 높이세요. 신발은 마법 저항력과 강인함을 주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. (P)\'서비스 시간\'으로 회복하는 그라가스의 유지력을 점화로 억제해야 킬각을 잡기 편해요.' },
    '그웬': { lv1: '그웬은 (P)\'가위 난도질\'을 통한 체력 회복 능력이 뛰어나니 1~2레벨에 무리하게 평타 교환을 하지 마세요. (Q)\'부식성 폭약\'으로 적절히 둔화시키며 거리를 유지하고, (Q)\'싹둑싹둑!\'의 중앙 고정 피해 범위에 들어가지 않도록 주의하세요. 첫 웨이브에서는 짧게 때리고 빠지는 교환만 반복하세요.', lv3: '그웬이 (W)\'신성한 안개\'를 켜면 대상 지정 공격이 불가능하지만, 위치 지정 스킬인 (Q)\'부식성 폭약\'은 안개 속에도 그대로 들어가요. (E)\'돌격가위\'로 진입하려 할 때 (E)\'경멸\'로 쳐내어 그웬을 뒤로 던지고 (W)\'심판의 원\'으로 빠르게 딜교환을 마무리하세요. 안개가 사라진 빈틈을 노려 공격적으로 나가는 게 좋아요.', lv6: '(R)\'바느질\'은 투사체라 둔화를 걸며 다가오니 (E)\'경멸\'의 보호막으로 피해를 흡수하며 거리 조절을 하세요. (R)\'불사의 공포\'는 투사체 스킬이라 (W)\'신성한 안개\'를 무시하고 맞힐 수 있으니 과감하게 발사하세요. 체력이 낮아진 그웬을 (R)\'불사의 공포\'로 처형해 주변 적까지 공포에 빠뜨리세요.', item: '신발은 마법 저항력을 제공하는 헤르메스의 발걸음을 선택해 그웬의 마법 피해를 줄이세요. 첫 코어 아이템으로는 공격력과 체력, 스킬 가속을 모두 챙길 수 있는 삼위일체를 추천해요.', spell: '점멸과 점화를 추천해요. 그웬의 (P)\'가위 난도질\' 회복 능력이 매우 뛰어나므로 점화로 체력 회복을 억제해야 킬각을 잡기 편해요.' },
    '나르': { lv1: '나르는 (Q)\'부메랑 던지기\'로 둔화를 걸며 견제하니 부메랑 궤적에서 벗어나 피해를 줄이세요. (Q)\'부식성 폭약\'을 먼저 맞힌 뒤 (W)\'심판의 원\'을 켜서 짧게 딜교환하는 것이 좋아요. (W)\'슝슝\' 추가 피해가 들어오는 공격을 맞지 않도록 주의하세요.', lv3: '나르가 (E)\'폴짝\'으로 진입하거나 거리를 벌릴 때 (E)\'경멸\'로 쳐내어 위치를 옮기세요. (Q)\'부식성 폭약\'으로 둔화를 걸고 (W)\'심판의 원\'으로 몰아치되, (P)\'분노 유전자\'가 가득 차 메가 나르로 변신하면 즉시 물러나세요. 메가 나르의 (W)\'쿵쾅\' 기절을 맞지 않는 것이 가장 중요해요.', lv6: '메가 나르의 (R)\'나르!\'에 맞아서 벽에 부딪히면 기절하니 벽 근처에서는 싸우지 마세요. 나르의 체력이 낮아지면 (R)\'불사의 공포\'를 맞혀 둔화를 걸고 처형 각을 보세요. 라인을 밀 때는 나르의 변신 타이밍을 확인하며 정글러의 개입에 대비하세요.', item: '삼위일체로 공격력과 체력을 챙겨 지속 교전 능력을 높이세요. 신발은 나르의 기본 공격 피해를 줄여주는 판금 장화가 적절해요.', spell: '점멸과 순간이동을 추천해요. 순간이동으로 라인 복귀를 빠르게 하고 운영에 집중하세요.' },
    '나서스': { lv1: '나서스가 (Q)\'흡수의 일격\'으로 미니언을 막타 쳐서 강화하려 할 때 (Q)\'부식성 폭약\'을 던져 둔화를 걸고 견제하세요. 막타 타이밍에 맞춰 압박하면 (Q)\'흡수의 일격\' 중첩을 쌓기 어려워져요. 초반에는 거리를 유지하며 무리하게 붙지 마세요.', lv3: '나서스의 (W)\'쇠약\'에 걸리면 이동 속도와 공격 속도가 점점 줄어들지만 둔화가 (E)\'경멸\'의 돌진을 막지는 못해요. 오래 맞을수록 속도가 계속 느려지니 (E)\'경멸\'로 먼저 들어가 기절을 시킨 뒤 (W)\'심판의 원\'으로 짧게 피해를 입히세요. (Q)\'부식성 폭약\'을 맞춰 표식을 남기고 싸우는 리듬을 유지하세요.', lv6: '나서스가 (R)\'사막의 분노\'를 사용해 체력과 방어력이 높아진 상태라면 무리하게 싸우지 마세요. 상대 체력이 낮아졌을 때 (R)\'불사의 공포\'를 사용하여 처형하면 킬을 가져오기 좋아요. 라인을 계속 밀어 넣어서 나서스가 (Q)\'흡수의 일격\'으로 중첩을 쌓지 못하게 방해하세요.', item: '첫 코어 아이템으로 갈라진 하늘을 선택하여 전투 지속력을 높이세요. 신발은 나서스의 (Q)\'흡수의 일격\' 물리 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 나서스의 생명력 흡수 효과를 줄이면서 킬각을 잡는 것이 중요해요.' },
    '녹턴': { lv1: '1~2레벨에는 녹턴의 (Q)\'황혼의 인도자\'로 인한 이동 속도 증가를 조심하며 거리를 유지하세요. (Q)\'부식성 폭약\'을 사용하여 녹턴의 체력을 깎아두는 것이 좋아요. 미니언 근처에서 상대의 접근을 경계하며 안정적으로 성장하세요.', lv3: '녹턴의 (W)\'어둠의 장막\'은 다음 스킬 하나를 막으니 (Q)\'부식성 폭약\'을 먼저 써서 보호막을 소모시킨 뒤 (E)\'경멸\'을 사용하세요. 녹턴이 (E)\'말할 수 없는 공포\'로 연결했다면 공포가 걸리기 전에 (E)\'경멸\'로 거리를 벌려 연결을 끊으세요. 녹턴의 공격 속도가 높아지는 구간을 주의하며 딜교환을 하세요.', lv6: '녹턴이 (R)\'피해망상\'을 사용해 시야를 차단하면 적극적인 교전은 피하는 것이 좋아요. 녹턴이 돌진해 붙으면 (E)\'경멸\'로 기절시켜 뒤로 던지고, 체력이 낮아지면 (R)\'불사의 공포\'로 처형하세요. 라인을 당겨두어 정글러의 개입에 대비하며 생존에 집중하세요.', item: '판금 장화와 삼위일체를 추천해요. 녹턴의 기본 공격 피해를 줄이고 전투력을 높이기 위해서예요.', spell: '점멸과 점화. 녹턴의 돌진에 대응하고 (R)\'불사의 공포\'와 함께 적을 빠르게 처치하기 위해서예요.' },
    '다리우스': { lv1: '1~2레벨에는 (P)\'과다출혈\' 중첩이 쌓이면 다리우스가 매우 강해지니 근접전을 피하세요. (Q)\'부식성 폭약\'으로 거리 조절을 하며 둔화를 걸고 짧게 툭툭 치는 식으로 견제하세요. 다리우스의 (Q)\'학살\' 도끼날 범위 밖에서 싸우며 체력 소모를 최소화하세요.', lv3: '(E)\'포획\'에 맞으면 끌려가 공중에 떠서 스킬을 쓸 수 없으니, 사거리에서 한 걸음 벗어난 위치를 유지하세요. 다리우스의 (W)\'마비의 일격\' 둔화가 걸리기 전에 (Q)\'부식성 폭약\'을 먼저 맞히고 (W)\'심판의 원\'으로 빠르게 딜교환을 끝내세요. 다리우스가 (Q)\'학살\'로 체력을 회복하기 전에 스킬을 다 쏟고 빠지는 것이 중요해요.', lv6: '(R)\'녹서스의 단두대\'는 (P)\'과다출혈\' 중첩이 높을수록 치명적이니 중첩이 쌓이면 즉시 거리를 벌리세요. 다리우스의 체력이 낮아지면 (R)\'불사의 공포\'를 맞춰 둔화를 걸고 처형 각을 보세요. (E)\'포획\'이 빠진 타이밍에 진입해 빠르게 딜교환을 하고 정글러를 부르면 처치하기 편해요.', item: '삼위일체를 첫 코어로 선택해 공격력과 체력, 공격 속도를 챙겨 짧은 교전에서 앞서가세요. 신발은 다리우스의 기본 공격 피해를 줄여 주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 다리우스의 (Q)\'학살\'을 통한 체력 회복을 억제하고 마무리 피해를 입히세요.' },
    '라이즈': { lv1: '라이즈는 (Q)\'과부하\'로 멀리서 견제하며 접근을 막으려 해요. (Q)\'부식성 폭약\'을 사용하여 라이즈의 움직임을 둔화시키며 거리를 조절하세요. 1~2레벨에는 스킬이 부족하니 무리하지 말고 미니언을 챙기며 대응해요.', lv3: '(E)\'주문 전이\'가 남은 상태에서 (W)\'룬 감옥\'을 맞으면 속박되니 주의하세요. (E)\'경멸\'로 먼저 진입하여 거리를 좁히고 라이즈가 스킬을 쓰기 전에 붙으세요. (W)\'심판의 원\'을 켜고 붙으면 라이즈가 거리를 벌리기 어려워져요.', lv6: '라이즈의 체력이 낮을 때 (R)\'불사의 공포\'를 사용하여 처형을 노리세요. 라이즈가 (R)\'공간 왜곡\'으로 빠지기 전에 (E)\'경멸\' 기절과 (W)\'심판의 원\'으로 최대한 피해를 넣어두는 것이 중요해요. 라이즈가 차원문을 열면 정글러가 올 수 있으니 라인을 너무 밀지 마세요.', item: '갈라진 하늘과 헤르메스의 발걸음을 선택하세요. 갈라진 하늘은 체력과 공격력을 높여주고 헤르메스의 발걸음은 강인함을 제공하여 (W)\'룬 감옥\'의 속박 시간을 줄여줘요.', spell: '점멸과 점화를 사용하세요. 라이즈가 거리를 벌리기 전에 (E)\'경멸\'과 함께 사용해 빠르게 압박하세요.' },
    '럼블': { lv1: '럼블은 (Q)\'화염방사기\'를 사용하여 근접 거리에서 지속적인 마법 피해를 입혀요. (Q)\'부식성 폭약\'을 맞춰 럼블의 움직임을 둔화시키며 거리를 조절하세요. 럼블이 열기를 모으기 전에는 평타와 (Q)\'부식성 폭약\'으로 견제하며 버티는 것이 좋아요.', lv3: '럼블이 (E)\'전기 작살\'로 마법 저항력을 낮추고 둔화를 걸면 거리를 벌려야 해요. (W)\'고철 방패\'가 켜진 동안은 피해가 흡수되니 방패가 빠진 뒤에 (E)\'경멸\'로 진입해 (W)\'심판의 원\'으로 지속 딜을 넣으세요. 럼블의 (Q)\'화염방사기\' 범위 안에서 너무 오래 머물지 않도록 (E)\'경멸\'의 보호막을 활용하세요.', lv6: '럼블이 (R)\'이퀄라이저 미사일\'을 깔면 불타는 궤적 위에서 벗어나 피해를 피하세요. 럼블의 체력이 낮아졌을 때 (R)\'불사의 공포\'를 사용하여 처형을 노리는 것이 핵심이에요. 럼블이 과열 상태에서 스킬을 못 쓰는 타이밍을 포착해 (E)\'경멸\'로 진입하면 효과적이에요.', item: '굶주린 히드라를 첫 코어로 올려서 전투 지속력을 높이세요. 신발은 럼블의 마법 피해를 줄여주는 마법 저항력이 있는 헤르메스의 발걸음을 신으세요.', spell: '점멸과 점화를 추천해요. 점화는 마무리 피해를 더해 (R)\'불사의 공포\' 처형 범위에 빠르게 들어가게 도와줘요.' },
    '레넥톤': { lv1: '1~2레벨에는 (Q)\'양떼 도륙\'으로 체력을 회복하며 버티는 레넥톤의 근접전이 강해요. (Q)\'부식성 폭약\'을 사용하여 사거리 밖에서 둔화를 걸고 짧게 견제하며 거리 조절을 하세요. 레넥톤이 분노를 쌓기 위해 평타를 치려 하면 뒤로 빠지며 피해를 최소화하세요.', lv3: '(E)\'자르고 토막내기\'로 진입해 (W)\'무자비한 포식자\' 기절을 넣는 레넥톤의 콤보를 주의하세요. (Q)\'부식성 폭약\'으로 둔화를 먼저 걸고 (W)\'심판의 원\'을 켜서 대응하되, 상대가 붙으면 (E)\'경멸\'로 기절시켜 뒤로 던지며 보호막을 얻으세요. 분노가 많이 쌓인 상태에서 (W)\'무자비한 포식자\'를 맞으면 보호막이 파괴되고 기절이 길어지니 분노 상태를 잘 확인하세요.', lv6: '(R)\'강신\'을 사용한 레넥톤은 체력이 늘어나고 분노가 빠르게 차오르니 정면 대결을 피하고 기다리세요. (R)\'강신\'의 효과가 끝난 뒤 체력이 낮아진 틈을 타 (R)\'불사의 공포\'를 맞히고 처형 각을 보세요. (E)\'자르고 토막내기\'의 재사용 돌진으로 빠져나가려 할 때 (E)\'경멸\'로 잡아두면 처형하기 훨씬 수월해요.', item: '삼위일체를 가서 공격력과 체력을 챙기고 스킬 가속으로 딜교환 횟수를 늘리세요. 신발은 레넥톤의 기본 공격 피해를 줄여주는 판금 장화가 효율적이에요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과로 (Q)\'양떼 도륙\'의 체력 회복량을 줄여야 킬각을 잡기 편해요.' },
    '렝가': { lv1: '렝가가 수풀에서 (P)\'보이지 않는 포식자\'로 도약하며 (Q)\'포악함\'을 사용해 공격하는 것을 경계하며 거리를 유지하세요. (Q)\'부식성 폭약\'을 적중시켜 둔화를 걸고 최대한 수풀에서 멀리 떨어져서 파밍을 진행하세요. 상대가 도약할 수 있는 경로를 예측하며 신중하게 움직여야 해요.', lv3: '렝가가 최대 야성 상태에서 (E)\'올가미 투척\'으로 속박하면 (E)\'경멸\' 돌진도 쓸 수 없으니 올가미가 날아오는 방향을 피해 움직이세요. 렝가가 도약해 붙은 뒤에 (E)\'경멸\'로 기절시켜 뒤로 던지고, (Q)\'부식성 폭약\'과 (W)\'심판의 원\'으로 상대가 (W)\'전투의 포효\'로 회복하기 전에 피해를 누적하세요. 상대의 야성 중첩이 낮을 때 빠르게 딜교환을 마치는 것이 좋아요.', lv6: '렝가가 (R)\'사냥의 전율\'로 위장해 도약해 오면 (E)\'경멸\'로 기절시켜 뒤로 던져 진입 흐름을 끊으세요. 상대의 체력이 낮아지면 (R)\'불사의 공포\'를 맞히고 처형 범위까지 체력을 깎아 제압하며 마무리하세요. 라인을 당겨서 정글러의 개입을 유도하고 수풀 근처에서의 정면 승부는 피하세요.', item: '판금 장화와 삼위일체를 선택하세요. 렝가의 기본 공격 피해를 줄이기 위해 판금 장화를 신고 삼위일체로 공격력과 체력을 보강해요.', spell: '점멸과 점화. (W)\'전투의 포효\'의 회복량을 줄이고 처형 각을 확실하게 잡기 위해 점화를 선택해요.' },
    '리븐': { lv1: '리븐은 (Q)\'부러진 날개\'를 사용하여 돌진하며 (P)\'룬 검\' 평타로 강하게 압박해요. 우르곳은 (Q)\'부식성 폭약\'을 리븐에게 맞춰 둔화를 걸고 사거리 조절을 하며 미니언을 챙기세요. 리븐이 들어올 때 무리하게 맞서지 말고 거리를 유지하는 것이 좋아요.', lv3: '(W)\'기 폭발\'은 사거리가 짧으니 기절을 맞지 않도록 리븐과의 거리를 유지하세요. 리븐의 (E)\'용맹\' 보호막이 사라진 뒤에 (W)\'심판의 원\'을 켜고 (Q)\'부식성 폭약\'을 맞히며 딜교환을 하세요. (E)\'경멸\'로 리븐을 뒤로 던지면 리븐의 스킬 연계를 끊고 안전하게 빠져나갈 수 있어요.', lv6: '리븐이 (R)\'추방자의 검\'을 사용해 사거리가 길어지면 체력이 적을 때 무리하게 맞서지 마세요. 리븐의 체력이 낮을 때 (R)\'불사의 공포\'를 사용하여 처형을 노리되 리븐의 궁극기 재사용 스킬을 조심하세요. 라인을 당겨 관리하며 정글러의 개입을 기다리는 것이 좋아요.', item: '판금 장화와 갈라진 하늘을 추천해요. 판금 장화는 기본 공격으로 받는 피해량을 줄여주고 갈라진 하늘은 공격력과 체력을 올려줘요.', spell: '점멸과 점화를 추천해요. 점화로 낮은 체력의 리븐을 확실히 마무리하세요.' },
    '리산드라': { lv1: '리산드라는 (Q)\'얼음 파편\'으로 멀리서 견제하며 둔화를 걸기 때문에 체력 관리에 신경 써야 해요. (Q)\'부식성 폭약\'을 적중시켜 둔화를 걸며 1~2레벨에 평타와 함께 압박해 보세요.', lv3: '리산드라의 (W)\'서릿발\'을 빼내기 위해 거리를 조절하며 (E)\'경멸\'로 빠르게 진입하여 적을 뒤로 던지세요. (Q)\'부식성 폭약\'으로 둔화를 먼저 걸고 (W)\'심판의 원\'을 사용하여 지속적인 피해를 입히세요.', lv6: '리산드라가 자신에게 (R)\'얼음 무덤\'을 써서 무적 상태가 되면 잠시 딜을 멈추고 기다려야 해요. 리산드라의 체력이 낮을 때 (R)\'불사의 공포\'를 맞히면 처형이 가능하므로 (E)\'경멸\'로 위치를 잡으세요. 리산드라가 (R)\'얼음 무덤\'으로 기절을 걸면 정글러의 개입에 취약해지니 라인을 너무 밀지 마세요.', item: '맬모셔스의 아귀를 첫 코어로 선택하여 마법 저항력을 높이고 생명선 효과로 버텨보세요. 신발은 (R)\'얼음 무덤\'의 기절 지속 시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 (R)\'얼음 무덤\'의 회복을 줄이면 무적이 끝난 뒤 마무리가 쉬워져요.' },
    '마스터이': { lv1: '마스터 이의 (P)\'2연속 공격\'은 초반 맞딜을 매우 강력하게 만들어요. 1~2레벨에는 무리하게 평타를 주고받지 말고 (Q)\'부식성 폭약\'을 맞춰서 거리를 조절하세요. 상대가 들어오려 할 때 둔화를 걸어 대응하는 것이 좋아요.', lv3: '마스터 이가 (Q)\'일격 필살\'을 사용하여 돌진할 때는 대상으로 지정할 수 없으니 주의하세요. 마스터 이가 (W)\'명상\'을 사용해 체력을 회복하고 피해를 줄인다면 (W)\'심판의 원\' 사용을 잠시 멈추는 게 좋아요. (E)\'경멸\'로 마스터 이를 기절시키고 뒤로 던진 뒤에 화력을 집중하세요.', lv6: '(R)\'최후의 전사\'를 켠 마스터 이는 둔화에 면역이라 (Q)\'부식성 폭약\'의 둔화가 통하지 않지만 (E)\'경멸\'의 기절은 통해요. 마스터 이의 체력이 낮아지면 (R)\'불사의 공포\'를 사용해 제압하고 처형하여 확실하게 잡으세요. 마스터 이가 킬을 올리면 스킬 쿨타임이 줄어드니 정글 개입 시 조심하세요.', item: '굶주린 히드라를 첫 코어로 가서 생명력 흡수를 챙기세요. 신발은 마스터 이의 평타 물리 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 마스터 이가 (W)\'명상\'으로 체력을 회복할 때 점화로 회복량을 줄여야 해요.' },
    '마오카이': { lv1: '마오카이가 (P)\'마법 흡수\'로 체력을 회복하며 평타를 치러 올 때 (Q)\'부식성 폭약\'을 맞춰 둔화시키세요. 1~2레벨에는 (Q)\'덤불 주먹\'에 밀려나지 않도록 거리 조절을 하며 미니언을 챙기세요.', lv3: '마오카이가 (W)\'뒤틀린 전진\'으로 속박을 걸려고 하면 사거리 밖에서 기다렸다가 (E)\'경멸\'로 먼저 진입해 기절을 시키세요. (W)\'뒤틀린 전진\' 중에는 대상으로 지정할 수 없으니 그 스킬이 빠지기를 확인한 뒤에 (Q)\'부식성 폭약\'과 (W)\'심판의 원\'으로 교환하세요. 속박에 걸리면 이동이 막히니 마오카이의 스킬이 빠진 것을 확인하고 싸우세요.', lv6: '마오카이의 체력이 낮아지면 (R)\'불사의 공포\'를 사용하여 처형을 노리세요. (R)\'대자연의 마수\'가 다가오면 벽에 닿아 속박되지 않도록 옆으로 이동하며 자리를 잡으세요. 마오카이가 (R)\'대자연의 마수\'로 라인을 압박하면 정글러를 불러 함께 대응하세요.', item: '헤르메스의 발걸음과 칠흑의 양날 도끼를 선택하세요. 마오카이의 마법 피해를 줄이고 단단한 체력을 깎기 위해서예요.', spell: '점멸과 점화. 마오카이의 체력이 낮을 때 (R)\'불사의 공포\'로 확실하게 처치하기 위해서예요.' },
    '말자하': { lv1: '말자하는 (P)\'공허 태세\'가 켜져 있으면 피해를 크게 줄이니 평타나 (Q)\'부식성 폭약\'으로 패시브를 먼저 벗겨내세요. (Q)\'공허의 부름\'은 두 문 사이로 파동이 지나가며 맞히는 스킬이라 미니언으로 막히지 않으니, 문이 열리는 위치를 보고 옆으로 피하세요. 1~2레벨에는 말자하의 사거리가 더 길기에 무리한 진입보다는 미니언을 챙기며 버티세요.', lv3: '말자하가 (E)\'재앙의 환상\'을 걸고 (W)\'공허의 무리\'를 소환하면 공허충들과 함께 지속 피해를 입으니 주의하세요. (E)\'경멸\'로 진입할 때는 말자하의 (Q)\'공허의 부름\' 침묵을 맞지 않도록 조심하며 적을 뒤로 던지세요. (Q)\'부식성 폭약\'을 맞춰 둔화시킨 뒤 (W)\'심판의 원\'을 사용해 딜교환을 하세요.', lv6: '말자하의 (R)\'황천의 손아귀\'는 제압이라 점멸이나 스킬로 풀 수 없으니 사용 타이밍을 잘 확인하세요. 말자하가 (R)\'황천의 손아귀\'로 제압을 걸기 전에 (E)\'경멸\'로 먼저 진입하여 기절을 시키는 것이 좋아요. 상대 체력이 낮아지면 (R)\'불사의 공포\'로 처형하여 빠르게 전투를 끝내세요.', item: '첫 코어 아이템으로는 공격력과 체력을 챙길 수 있는 삼위일체를 추천해요. 신발은 마법 저항력과 강인함을 주는 헤르메스의 발걸음을 신으세요.', spell: '점멸과 점화를 추천해요. (R)\'황천의 손아귀\'는 제압이라 정화로 풀 수 없으니 정화 대신 점화로 마무리 피해를 챙기세요.' },
    '말파이트': { lv1: '말파이트는 (P)\'화강암 방패\'로 피해를 흡수하며 (Q)\'지진의 파편\'으로 견제하는데, 이는 대상 지정 스킬이라 미니언 뒤에 숨어도 피할 수 없어요. (Q)\'부식성 폭약\'을 사용하여 말파이트의 방패를 먼저 벗긴 뒤에 (W)\'심판의 원\'을 활용한 짧은 딜교환을 시도하세요. 방패가 재생성되기 전에 압박하여 말파이트가 편하게 파밍하지 못하도록 관리해야 해요.', lv3: '말파이트가 (E)\'지면 강타\'를 사용하면 공격 속도가 감소하므로 주의해야 해요. (E)\'경멸\'을 사용하여 말파이트를 기절시킨 뒤 (W)\'심판의 원\'으로 지속적인 피해를 입히는 것이 중요해요. 말파이트의 (Q)\'지진의 파편\'은 피할 수 없으니 거리 조절을 하며 자신의 스킬을 정확히 맞히는 것에 집중하세요.', lv6: '말파이트의 (R)\'멈출 수 없는 힘\'은 저지 불가 돌진이라 군중 제어로 막을 수 없고 맞으면 공중에 떠서 스킬을 쓸 수 없어요. (E)\'경멸\'로 진입하여 말파이트를 뒤로 던진 후, 체력이 낮은 말파이트에게 (R)\'불사의 공포\'를 사용해 처형을 노리세요. 말파이트의 궁극기가 빠진 타이밍에 정글러와 함께 압박하면 킬을 가져오기 좋아요.', item: '헤르메스의 발걸음과 칠흑의 양날 도끼를 추천해요. 말파이트는 스킬 피해가 마법 피해 위주라 헤르메스의 발걸음이 맞고, 칠흑의 양날 도끼는 방어력이 높은 말파이트의 방어력을 깎아줘요.', spell: '점멸과 점화를 사용하세요. 점화로 말파이트의 체력을 낮춰 (R)\'불사의 공포\'로 확실하게 마무리할 수 있어요.' },
    '모데카이저': { lv1: '모데카이저의 (Q)\'말살\'은 범위 안의 모든 적을 때리고 단일 대상에게 맞으면 피해가 커지니, 미니언 뒤에 선다고 피해가 줄지 않아요. 맞는 위치에서 비켜 서며 (Q)\'부식성 폭약\'을 맞춰 둔화시키고 거리를 조절하세요. 평타와 (P)\'화염의 메아리\'로 짧게 압박하며 라인을 관리하세요.', lv3: '모데카이저가 (E)\'죽음의 손아귀\'로 끌어당기려 하면 (E)\'경멸\'을 사용해 보호막을 얻으며 대응하거나 거리를 벌리세요. 모데카이저가 (W)\'불멸\'로 보호막을 만들며 버티기 전에 (Q)\'부식성 폭약\'과 (W)\'심판의 원\'을 연계해 빠르게 피해를 입히는 것이 중요해요.', lv6: '(R)\'죽음의 세계\'에 끌려가면 순간이동이나 궁극기로 빠져나갈 수 없고 능력치도 일부 빼앗기니, 모데카이저의 궁극기가 빠질 때까지 무리한 교전을 피하세요. 모데카이저의 체력이 낮아졌을 때 (R)\'불사의 공포\'를 사용하면 처형을 노릴 수 있어요. 라인을 당겨 두어 정글러와 함께 대응하세요.', item: '갈라진 하늘을 첫 코어로 선택해 전투 지속력을 높이고 피해를 입히세요. 신발은 모데카이저의 마법 피해를 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 모데카이저가 (W)\'불멸\'을 사용해 체력을 회복하는 것을 점화로 감소시켜 킬각을 잡을 수 있어요.' },
    '문도박사': { lv1: '문도 박사가 (Q)\'오염된 뼈톱\'을 던지면 처음 맞는 적에게 맞으니 미니언 뒤에 서서 피하며 거리를 유지하세요. (Q)\'부식성 폭약\'을 적중시켜 문도 박사를 둔화시키고 평타로 압박하세요. 패시브 (P)\'가고 싶은 데로 간다\'는 처음 적중하는 기절 같은 이동 불가 효과에 저항하니 재사용 대기 중인지 확인하세요.', lv3: '문도 박사가 (W)\'심장 전기 충격\'을 켜고 다가오면 저장된 피해로 회복할 수 있으니 근접 교환을 피하세요. (E)\'경멸\'을 사용하여 문도 박사를 기절시키고 (W)\'심판의 원\'으로 빠르게 피해를 입히는 것이 중요해요. 문도 박사의 (Q)\'오염된 뼈톱\'이 미니언에 막히는 타이밍을 이용해 딜교환을 시도하세요.', lv6: '문도 박사가 (R)\'최대 투여량\'을 사용해 체력을 회복할 때는 무리하게 싸우지 말고 뒤로 물러나세요. 문도 박사의 체력이 일정 수준 이하로 떨어지면 (R)\'불사의 공포\'를 사용해 처형하며 킬을 노리세요. 문도 박사가 궁극기를 사용한 직후에는 라인을 관리하며 정글러와 함께 압박을 시도하세요.', item: '문도 박사의 마법 피해를 줄이기 위해 헤르메스의 발걸음을 신발로 가세요. 첫 코어 아이템으로는 높은 체력을 가진 문도 박사를 상대하기 좋은 칠흑의 양날 도끼를 선택하세요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과로 문도 박사의 (R)\'최대 투여량\'과 (Q)\'오염된 뼈톱\' 회복량을 줄여야 해요.' },
    '바루스': { lv1: '바루스는 (Q)\'꿰뚫는 화살\'을 오래 충전해 먼 거리에서 강하게 견제하니, 옆으로 움직이며 화살을 최대한 피하세요. (Q)\'부식성 폭약\'을 맞춰 둔화시키며 거리를 좁히려 노력하고, 1~2레벨 구간은 체력 관리를 하며 무리하게 딜교환하지 마세요.', lv3: '바루스가 (W)\'역병 화살\'을 묻힌 뒤 (E)\'퍼붓는 화살\'로 터뜨려 최대 체력 비례 피해를 주니, 평타를 맞았다면 장판 스킬을 조심하세요. (Q)\'부식성 폭약\'으로 둔화를 건 뒤 (E)\'경멸\'로 돌진해 바루스를 뒤로 넘기고 (W)\'심판의 원\'으로 빠르게 화력을 쏟아부으세요.', lv6: '(R)\'부패의 사슬\'에 맞으면 속박되어 진입이 막히니, 바루스의 궁극기가 빠진 것을 확인하고 (E)\'경멸\'로 진입하세요. 체력이 낮아진 바루스에게 (R)\'불사의 공포\'를 맞히면 제압하여 처형할 수 있으니 킬각을 잘 잡으세요. 라인을 밀어넣고 정글러와 함께 덮쳐 바루스를 빠르게 제압하세요.', item: '판금 장화와 삼위일체를 추천해요. 판금 장화는 바루스의 기본 공격 피해를 줄여주고, 삼위일체는 공격력과 체력을 제공해 교전 능력을 높여줘요.', spell: '점멸과 유체화를 추천해요. 유체화의 이동 속도로 원거리 챔피언인 바루스와의 거리를 빠르게 좁힐 수 있어요.' },
    '베인': { lv1: '베인은 (W)\'은화살\'의 세 번째 타격이 강력하니 평타를 맞기 전에 거리를 두세요. (Q)\'부식성 폭약\'으로 베인에게 둔화를 걸어 접근을 준비하고 첫 웨이브를 안정적으로 가져가세요. 베인이 (Q)\'구르기\'로 거리를 벌리는 것을 의식하며 무리하게 따라가지 마세요.', lv3: '(E)\'경멸\'로 진입하여 기절을 노리되 베인이 (Q)\'구르기\'를 사용해 도망가지 않게 조심하세요. (E)\'선고\'를 맞아 벽에 부딪히면 기절하니 벽 근처에서는 (E)\'경멸\' 사용에 주의하세요. (Q)\'부식성 폭약\'을 맞힌 뒤 (W)\'심판의 원\'을 사용하여 베인의 체력을 깎으세요.', lv6: '베인의 체력이 낮아지면 (R)\'불사의 공포\'로 제압하고 처형할 각을 보세요. 베인이 (R)\'결전의 시간\'을 켜면 (Q)\'구르기\'를 통해 투명 상태가 되니 주의해야 해요. 베인이 (E)\'선고\'로 밀쳐내기 전에 (E)\'경멸\'을 성공시켜야 킬을 낼 수 있어요.', item: '베인의 기본 공격 물리 피해를 줄이기 위해 판금 장화가 좋아요. 첫 코어 아이템으로는 체력과 공격력을 모두 제공하는 갈라진 하늘을 추천해요.', spell: '점멸과 점화를 추천해요. 베인이 (Q)\'구르기\'로 도망치기 전에 점화의 마무리 피해를 더해 (R)\'불사의 공포\' 처형 범위까지 빠르게 깎으세요.' },
    '볼리베어': { lv1: '볼리베어가 (Q)\'번개 강타\'로 빠르게 접근하며 기절을 노리니 거리를 잘 조절하세요. (Q)\'부식성 폭약\'을 적중시켜 둔화를 걸고 거리를 유지하며 안정적으로 라인을 파밍하세요. 초반에는 볼리베어의 교환이 강하니 무리한 진입은 피해야 해요.', lv3: '볼리베어가 (W)\'광란의 상처\'로 체력을 회복하지 못하도록 표식이 남은 상태에서 주의 깊게 대응하세요. (E)\'천공 분열\' 범위 내에서 볼리베어가 보호막을 얻을 수 있으니 번개가 떨어지는 위치를 피하며 (E)\'경멸\'로 거리를 벌리세요. 볼리베어의 (Q)\'번개 강타\'가 빠진 시점에 (W)\'심판의 원\'을 활용해 딜교환을 시도하세요.', lv6: '볼리베어가 (R)\'폭풍을 부르는 자\'를 사용해 포탑을 무력화하며 다이브를 할 수 있으니 주의하세요. 체력이 낮은 볼리베어에게 (R)\'불사의 공포\'를 적중시켜 처형까지 노리는 플레이가 필요해요. 볼리베어가 궁극기로 들어오는 타이밍을 조심하며 라인 관리를 철저히 하세요.', item: '삼위일체를 첫 코어로 선택해 전투력을 높이세요. 신발은 볼리베어의 마법 피해와 군중 제어 효과에 대응하기 위해 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 볼리베어가 (W)\'광란의 상처\'를 통해 체력을 회복하는 것을 점화로 억제하세요.' },
    '블라디미르': { lv1: '블라디미르는 (Q)\'수혈\'로 체력을 흡수하며 견제하니 미니언 뒤에 숨지 말고 거리 조절에 집중하세요. (Q)\'수혈\'은 대상 지정 기술이라 피할 수 없으니 피해를 최소화하며 (Q)\'부식성 폭약\'으로 같이 둔화를 걸어 주세요. 초반에는 무리하게 붙기보다 체력 관리를 하며 경험치를 챙기는 것이 좋아요.', lv3: '(W)\'피의 웅덩이\' 상태일 때는 대상으로 지정할 수 없으니 (E)\'경멸\'을 함부로 쓰지 말고 웅덩이가 끝난 뒤에 사용하세요. (E)\'선혈의 파도\'는 미니언이 가로막을 수 있으니 미니언 뒤에 서서 피해를 줄이세요. (Q)\'부식성 폭약\'으로 둔화를 먼저 걸고 (W)\'심판의 원\'으로 화력을 퍼부으며 압박하세요.', lv6: '(R)\'혈사병\'에 감염되면 받는 피해가 늘어나니 감염된 동안에는 거리 조절을 하며 뒤로 물러나세요. 블라디미르의 체력이 낮아졌을 때 (R)\'불사의 공포\'를 맞춰 처형각을 보세요. 라인을 밀어 포탑 근처에서 싸우면 상대의 도주 경로를 제한하기 편해요.', item: '헤르메스의 발걸음과 맬모셔스의 아귀를 추천해요. 마법 저항력을 높이고 생명선 보호막으로 (Q)\'수혈\'의 폭발적인 피해를 견디기 위해서예요.', spell: '점멸과 점화를 추천해요. 블라디미르가 (Q)\'수혈\'로 계속 체력을 회복하기 때문에 점화의 치유 감소 효과가 꼭 필요해요.' },
    '뽀삐': { lv1: '(Q)\'부식성 폭약\'으로 뽀삐를 둔화시키며 일방적인 견제를 하세요. 뽀삐가 (Q)\'망치 강타\'를 사용하여 바닥에 만든 둔화 지대를 밟지 않도록 주의하며 거리를 조절하세요. 뽀삐가 방패를 던져 (P)\'강철의 외교관\' 보호막을 얻기 전까지 짧게 딜교환을 하며 압박하세요.', lv3: '뽀삐가 (W)\'굳건한 태세\'를 켜면 (E)\'경멸\' 돌진이 막히고 둔화되니, 이 스킬이 빠진 것을 확인한 뒤에 진입하세요. (Q)\'부식성 폭약\'을 먼저 맞힌 뒤 (W)\'심판의 원\'으로 화력을 쏟아내며 딜교환을 하세요. 뽀삐의 (E)\'용감한 돌진\'에 밀려 벽에 부딪히면 기절하니 벽에서 떨어진 중앙 지역에서 싸우세요.', lv6: '(R)\'불사의 공포\'를 맞히고 체력이 낮아진 뽀삐를 제압하여 처치하세요. 뽀삐가 (R)\'수호자의 심판\'으로 멀리 날려버리면 (W)\'심판의 원\' 사격이 끊기니 거리 조절에 유의하세요. 라인을 밀어 포탑 아래에 둔 뒤 뽀삐가 (E)\'용감한 돌진\'으로 무리하게 들어올 때를 노려 반격하세요.', item: '삼위일체를 첫 코어로 가서 공격력과 체력을 높이고 딜교환 효율을 올리세요. 신발은 뽀삐의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 순간이동을 추천해요. 뽀삐는 (W)\'굳건한 태세\'로 (E)\'경멸\' 진입을 막아 킬각이 잘 나지 않으니 순간이동으로 라인 손실을 줄이고 합류에 대비하세요.' },
    '사이온': { lv1: '사이온의 (E)\'학살자의 포효\'는 미니언에 맞으면 미니언이 밀려나며 뒤의 적까지 맞히니 미니언 뒤로 숨지 말고 거리를 두세요. (Q)\'대량 학살 강타\'를 충전하는 동작이 보이면 옆으로 비켜서서 피해를 피하세요. (Q)\'부식성 폭약\'을 맞혀 둔화시킨 뒤 기본 공격으로 틈틈이 견제하며 거리를 조절하세요.', lv3: '(W)\'영혼의 용광로\' 보호막이 켜져 있을 때는 피해가 보호막에 먼저 흡수되니 폭발한 이후에 딜교환을 하세요. 사이온이 (Q)\'대량 학살 강타\'를 충전하는 모습이 보이면 범위 밖으로 빠지고, 내려친 뒤에 (E)\'경멸\'로 진입하세요. (Q)\'부식성 폭약\'으로 적중시킨 뒤 (W)\'심판의 원\'을 켜서 지속적인 물리 피해를 입히세요.', lv6: '(R)\'멈출 수 없는 맹공\'은 저지 불가 상태로 돌진해오니 직선 경로에서 옆으로 비켜나 기절을 피하세요. 사이온의 체력이 낮아지면 (R)\'불사의 공포\'로 처형을 노리되 (P)\'영광스러운 죽음\'으로 되살아나 공격할 수 있으니 주의하세요. 사이온이 궁극기로 다른 곳에 개입했다면 빠르게 라인을 밀어 포탑에 압박을 넣으세요.', item: '삼위일체와 판금 장화를 추천해요. 삼위일체로 공격력과 공격 속도를 높여 지속 딜을 넣고 판금 장화의 효과로 사이온의 기본 공격 피해를 줄이세요.', spell: '점멸과 순간이동을 추천해요. 사이온은 라인 유지력이 높고 라인을 길게 밀기 때문에 순간이동으로 복귀하며 손실을 줄이는 것이 중요해요.' },
    '사일러스': { lv1: '1~2레벨에는 사일러스가 (Q)\'사슬 후려치기\'로 견제하며 (P)\'페트리사이트 폭발\'을 쌓으려 하니 사슬이 교차하는 지점을 피하며 거리 조절을 하세요. (Q)\'부식성 폭약\'을 맞춰 사일러스를 둔화시킨 뒤에 기본 공격으로 압박하는 것이 좋아요. 사일러스가 스킬을 사용해 충전량을 쌓았을 때는 무리하게 붙지 마세요.', lv3: '사일러스가 (W)\'국왕시해자\'를 사용하여 체력을 회복하는 타이밍을 피해 딜교환을 하세요. 사일러스가 (E)\'도주 / 억압\'을 사용해 날아오를 때 (E)\'경멸\'을 사용해 기절을 맞히면 전투를 주도할 수 있어요. 사일러스의 (Q)\'사슬 후려치기\'가 지나간 자리에 서 있지 않도록 주의하며 (Q)\'부식성 폭약\'으로 거리를 조절하세요.', lv6: '사일러스는 내가 궁극기를 썼는지와 상관없이 (R)\'강탈\'로 (R)\'불사의 공포\'를 훔쳐 쓸 수 있으니 체력이 낮을 때 조심하세요. (E)\'경멸\'로 사일러스를 기절시킨 뒤 (W)\'심판의 원\'으로 피해를 입히고, 체력이 낮아지면 (R)\'불사의 공포\'로 처형을 노리세요. 사일러스가 훔친 궁극기를 사용하러 올 수 있으니 정글러의 위치를 확인하며 라인을 관리하세요.', item: '첫 코어 아이템으로 갈라진 하늘을 선택해 전투 지속력을 높이세요. 신발은 사일러스의 마법 피해를 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 사일러스가 (W)\'국왕시해자\'로 체력을 회복하는 것을 점화로 억제할 수 있어요.' },
    '세주아니': { lv1: '(Q)\'부식성 폭약\'을 사용하여 적절한 거리에서 견제하며 세주아니의 (W)\'혹한의 서릿발\' 사용을 경계해요. 상대가 서리 갑옷을 얻지 못하도록 미니언과 함께 꾸준히 피해를 입히는 것이 좋아요.', lv3: '세주아니의 (Q)\'혹한의 맹습\'이 빠진 직후에 (E)\'경멸\'로 진입하여 (W)\'심판의 원\'을 활용해 딜교환을 시도해요. 상대의 (E)\'만년 서리\' 스택이 쌓여 기절하기 전에 빠르게 교전을 마무리하세요.', lv6: '세주아니의 체력이 일정 수준 이하일 때 (R)\'불사의 공포\'를 사용하여 확실하게 처형할 수 있어요. 상대의 (R)\'빙하 감옥\'에 맞으면 움직이기 어려우니 라인 관리를 하며 정글러를 부르세요.', item: '삼위일체와 헤르메스의 발걸음을 가요. 삼위일체로 공격력을 높이고 헤르메스의 발걸음으로 세주아니의 군중 제어 지속시간을 줄여요.', spell: '점멸과 점화를 추천해요. 세주아니를 처치하기 위해 점화를 선택해요.' },
    '세트': { lv1: '세트는 (Q)\'주먹다짐\'을 사용하여 이동 속도를 높이며 다가오고 다음 공격에 피해를 얹으니 무리하게 싸우지 마세요. (Q)\'부식성 폭약\'으로 세트에게 둔화를 묻히며 거리 조절을 하고 미니언을 챙기며 버티세요. 1~2레벨 구간은 세트가 적극적으로 압박할 수 있으니 주의가 필요해요.', lv3: '세트의 (W)\'강펀치\'는 받은 피해를 투지로 모아 보호막과 고정 피해를 주니, 투지가 쌓인 상태에서 중심부에 맞지 않도록 (E)\'경멸\'로 위치를 잡으세요. 세트의 (E)\'안면 강타\'가 빠진 것을 확인하고 (E)\'경멸\'로 진입하여 (W)\'심판의 원\'으로 지속적인 피해를 입히세요. 세트의 스킬을 피하며 싸우는 것이 중요해요.', lv6: '세트가 (R)\'대미 장식\'으로 나를 붙잡아 내리꽂을 수 있으니 체력이 낮을 때 주의하세요. 세트의 체력이 낮아지면 (R)\'불사의 공포\'를 사용하여 처형하고 주변 적에게 공포를 입히세요. 세트가 궁극기를 사용한 뒤에는 다시 붙잡을 수 없으니 (E)\'경멸\'로 빠르게 진입해 승부를 보되 라인은 적절히 관리하세요.', item: '세트의 물리 피해를 줄이기 위해 판금 장화를 먼저 선택하세요. 첫 코어 아이템은 갈라진 하늘로 가서 체력과 공격력을 챙기며 교전 능력을 높이세요.', spell: '점멸과 점화를 추천해요. 세트는 (P)\'투기장의 투지\'로 잃은 체력에 비례해 체력을 회복하니 점화로 회복 효과를 줄이세요.' },
    '쉔': { lv1: '쉔은 (Q)\'황혼 강습\'으로 최대 체력 비례 피해를 주며 (P)\'기 보호막\'을 얻으니 맞딜을 조심하세요. (Q)\'부식성 폭약\'을 맞춰 쉔을 둔화시킨 뒤 평타로 견제하며 거리를 유지하세요. 쉔의 (Q)\'황혼 강습\'이 지나가는 길목을 피해 미니언과 함께 파밍하는 것이 좋아요.', lv3: '쉔이 (W)\'의지의 결계\'를 사용하면 결계 안의 아군에 대한 기본 공격이 차단되니 (W)\'심판의 원\' 사격을 함부로 쓰지 마세요. 쉔의 (E)\'그림자 돌진\'에 맞으면 도발당해 스킬을 쓸 수 없으니 돌진 사거리 밖에서 기다리고, 스킬이 빠진 뒤에 (E)\'경멸\'로 진입하세요. (Q)\'부식성 폭약\'을 먼저 맞힌 뒤 (E)\'경멸\'로 진입하면 교환의 흐름을 가져올 수 있어요.', lv6: '쉔이 (R)\'단결된 의지\'를 써서 다른 라인으로 이동하면 빠르게 라인을 밀어 압박하세요. 쉔의 체력이 낮을 때 (R)\'불사의 공포\'를 사용하여 처형하고 주변 적에게 공포를 입히세요. (E)\'경멸\'의 보호막을 활용해 쉔의 스킬 피해를 버티며 싸우는 것이 중요해요.', item: '갈라진 하늘을 첫 코어로 가서 체력과 공격력을 챙기세요. 신발은 쉔의 군중 제어 지속시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 쉔이 (E)\'그림자 돌진\'을 쓰기 전에 점화로 체력을 깎아 (R)\'불사의 공포\' 킬각을 잡으세요.' },
    '쉬바나': { lv1: '쉬바나가 (Q)\'잉걸불 일격\'으로 다가오면 (Q)\'부식성 폭약\'을 사용하여 거리를 유지하세요. 초반에는 쉬바나의 공격적인 움직임에 맞춰 무리하게 맞붙기보다 웨이브를 받아먹는 데 집중해요.', lv3: '쉬바나가 (E)\'용암 분출\'로 둔화를 걸려고 하면 (W)\'심판의 원\'을 사용하여 둔화 저항을 높이세요. (E)\'경멸\'로 거리를 조절하며 상대의 (Q)\'잉걸불 일격\'을 피하는 것이 중요해요.', lv6: '쉬바나가 (R)\'용의 강림\'으로 돌진할 때 (E)\'경멸\'로 막으려 하기보다 위치를 옮겨 피하세요. 상대 체력이 낮아졌을 때 (R)\'불사의 공포\'를 사용해 처형을 노리되 용 형상의 체력 회복을 주의하세요.', item: '헤르메스의 발걸음과 칠흑의 양날 도끼를 추천해요. 쉬바나의 마법 피해를 줄이면서 칠흑의 양날 도끼로 방어력을 깎아 피해량을 높여요.', spell: '점멸과 점화. 점화는 쉬바나의 회복 효과를 줄이는 데 도움을 주며 점멸은 (E)\'경멸\'과 연계해 변수를 만들기 좋아요.' },
    '스웨인': { lv1: '스웨인은 (Q)\'죽음의 손길\'로 멀리서 견제하고 (P)\'굶주린 새떼\'로 체력을 회복해요. (Q)\'부식성 폭약\'을 맞혀 둔화를 걸고 (P)\'화염의 메아리\'를 활용해 짧게 교전하며 체력 차이를 만드세요. 스웨인이 영혼 조각을 모아 최대 체력을 늘리기 전에 압박하는 것이 중요해요.', lv3: '스웨인이 (E)\'속박명령\'을 사용해 파동을 날리면 (E)\'경멸\'의 보호막을 믿고 궤적을 피하며 진입하세요. (E)\'속박명령\'에 걸리면 끌려가니 주의해야 하지만 (E)\'경멸\'로 스웨인을 뒤로 던지면 딜교환에서 앞설 수 있어요. (Q)\'부식성 폭약\'으로 둔화를 먼저 걸고 (W)\'심판의 원\'을 사용하는 것이 좋아요.', lv6: '스웨인이 (R)\'악의 승천\'을 켜고 생명력을 흡수할 때는 무리하게 맞붙기보다 거리를 조절하며 미니언을 챙기세요. 스웨인의 체력이 낮아졌을 때 (R)\'불사의 공포\'를 사용해 확실하게 처형하는 것이 핵심이에요. 스웨인이 변신 중일 때는 (E)\'경멸\'로 거리를 벌리거나 정글러와 함께 압박하세요.', item: '굶주린 히드라를 코어 아이템으로 가서 라인 푸시력과 생명력 흡수를 챙기세요. 신발은 스웨인의 마법 피해를 줄이고 CC 지속시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 스웨인은 (P)\'굶주린 새떼\'와 (R)\'악의 승천\'으로 체력을 계속 회복하니 점화로 회복량을 줄여 주세요.' },
    '스카너': { lv1: '(Q)\'부식성 폭약\'을 사용하여 적의 접근을 늦추고 거리 조절을 하며 견제하세요. 상대가 (Q)\'부서진 대지/지반 돌출\'로 강화된 평타를 치러 올 때 정면으로 맞서지 말고 옆으로 피하며 피해를 최소화해요.', lv3: '스카너의 (E)\'이쉬탈의 격돌\'에 붙잡히면 벽까지 끌려가 기절하니 벽 근처에서는 싸우지 마세요. 돌진이 빠진 것을 확인하고 (Q)\'부식성 폭약\'으로 둔화를 건 뒤 (W)\'심판의 원\'을 켜서 짧은 교전에서 화력을 쏟아내요.', lv6: '(R)\'꿰뚫기\'에 제압당하면 아무런 행동을 할 수 없으니 상대의 꼬리 사거리를 주의하며 움직이세요. 체력이 낮은 적에게 (R)\'불사의 공포\'를 적중시켜 빠르게 처형하고 주변 적에게 공포를 걸어 상황을 정리해요.', item: '판금 장화와 삼위일체를 추천해요. 판금 장화는 (Q)\'부서진 대지/지반 돌출\'의 기본 공격 피해를 줄여주고 삼위일체는 공격력과 체력을 높여줘요.', spell: '점멸과 순간이동을 사용하세요. (R)\'꿰뚫기\'의 사거리 밖으로 빠르게 벗어나거나 킬각을 잡기 위해 점멸이 필요하고 라인 관리를 위해 순간이동을 선택해요.' },
    '신지드': { lv1: '신지드가 (Q)\'맹독의 자취\'를 켜고 주변을 돌며 피해를 입히려 해요. (Q)\'부식성 폭약\'을 적중시켜 둔화시키고 거리를 유지하며 미니언 막타를 챙기세요. 신지드가 너무 가까이 붙으면 (P)\'독성 급류\'로 이동 속도가 증가하니 무리하게 쫓지 마세요.', lv3: '(W)\'초강력 접착제\' 위에 서 있으면 이동 스킬인 (E)\'경멸\'을 쓸 수 없으니 접착제 범위에서 벗어난 뒤에 사용하세요. (E)\'던져넘기기\'에 맞지 않게 주의하며, 상대가 다가올 때 (Q)\'부식성 폭약\'으로 둔화시킨 뒤 (W)\'심판의 원\'으로 피해를 입히세요. 신지드의 (W)\'초강력 접착제\'가 빠진 타이밍에 (E)\'경멸\'로 진입해 딜교환을 시도하세요.', lv6: '(R)\'광기의 물약\'을 사용한 신지드는 체력 재생과 방어 능력이 상승하니 정면 대결을 피하세요. (R)\'불사의 공포\'를 맞춰 둔화시킨 뒤 체력이 낮아지면 재사용해 처형하세요. 신지드가 (W)\'초강력 접착제\'를 깔고 도망치면 접착제를 돌아가서 (E)\'경멸\'로 기절시켜 뒤로 던지고 정글러와 함께 킬각을 잡으세요.', item: '삼위일체와 헤르메스의 발걸음을 추천해요. 삼위일체로 공격력과 체력을 높이고, 헤르메스의 발걸음으로 (E)\'던져넘기기\'와 (W)\'초강력 접착제\' 연계의 속박 지속시간을 줄이세요.', spell: '점멸과 순간이동을 추천해요. 신지드가 라인을 빠르게 밀어내므로 순간이동으로 손실을 줄이고 합류전에 대비하세요.' },
    '아이번': { lv1: '1~2레벨에는 (Q)\'부식성 폭약\'을 활용해 아이번의 체력을 깎으며 거리를 유지하세요. 아이번이 (W)\'수풀 가꾸기\'로 시야를 가리려 하면 무리하게 들어가지 말고 미니언을 챙기며 대응해요. (Q)\'부식성 폭약\'의 둔화 효과를 이용해 아이번이 다가오지 못하게 관리하는 것이 중요해요.', lv3: '(E)\'경멸\'로 돌진한 뒤 (W)\'심판의 원\'을 사용하여 지속적인 물리 피해를 입히세요. 아이번의 (Q)\'덩굴뿌리\'에 맞으면 움직임이 제한되니 조심하며 상대의 속박을 피하는 것이 핵심이에요. (E)\'경멸\'로 얻는 보호막을 이용해 아이번의 (E)\'보호의 씨앗\' 피해를 버티며 싸워요.', lv6: '아이번의 체력이 낮을 때 (R)\'불사의 공포\'를 사용하면 확실하게 처형할 수 있어요. 아이번이 (R)\'데이지!\'를 소환하면 (R)\'데이지!\'의 공중으로 띄우는 효과를 조심하며 전투를 이어가세요. 라인을 밀어 넣은 뒤 정글러의 개입을 유도하여 압박을 가해요.', item: '헤르메스의 발걸음과 갈라진 하늘을 선택하세요. 아이번의 마법 피해에 저항하기 위해 헤르메스의 발걸음을 가고 전투 지속력을 높이기 위해 갈라진 하늘을 올려요.', spell: '점멸과 점화. (E)\'경멸\'의 진입 거리를 보완하기 위해 점멸을 사용하고 아이번을 빠르게 처단하기 위해 점화를 선택해요.' },
    '아지르': { lv1: '1~2레벨에는 (W)\'일어나라!\'와 (Q)\'사막의 맹습\'을 활용한 견제가 매우 강해요. (Q)\'사막의 맹습\'은 모래 병사가 통과하는 모든 적을 맞히니 미니언 뒤에 숨어도 피해를 줄일 수 없어요. 무리하게 다가가기보다 (Q)\'부식성 폭약\'으로 거리 조절을 하며 경험치만 챙기세요.', lv3: '(Q)\'부식성 폭약\'을 먼저 맞힌 뒤 (E)\'경멸\'로 빠르게 진입해 (W)\'심판의 원\'을 켜세요. 상대가 (E)\'신기루\'로 도망치거나 보호막을 쓰기 전에 딜교환을 마쳐야 해요. (E)\'신기루\'가 빠진 타이밍을 노려 진입하면 훨씬 편하게 공격할 수 있어요.', lv6: '(R)\'불사의 공포\'를 맞춰 둔화시킨 뒤 (E)\'경멸\'로 접근해 처형 각을 보세요. 상대가 (R)\'황제의 진영\'으로 밀어낼 수 있으니 진입 타이밍을 신중하게 잡으세요. 라인을 당겨서 정글러를 부르면 상대의 도주 경로를 차단하기 좋아요.', item: '삼위일체와 헤르메스의 발걸음이에요. 삼위일체로 공격력과 체력을 챙기고 헤르메스의 발걸음의 마법 저항력으로 상대 마법 피해를 줄이세요.', spell: '점멸과 순간이동이에요. 원거리 챔피언의 견제로 인해 라인 복귀와 관리가 중요하기 때문이에요.' },
    '아칼리': { lv1: '아칼리는 (Q)\'오연투척검\'으로 견제하며 (P)\'암살자의 표식\' 원을 이용해 강화 평타를 노려요. (Q)\'부식성 폭약\'을 적절히 맞춰 둔화를 걸어 거리를 조절하고, 아칼리가 평타 사거리를 늘려 진입할 때 같이 때려주세요. 무리하게 쫓기보다 첫 웨이브를 받아내며 체력을 관리하세요.', lv3: '(W)\'황혼의 장막\' 안의 아칼리는 대상으로 지정할 수 없으니, (Q)\'부식성 폭약\' 같은 범위 스킬로 둔화를 먼저 거세요. (E)\'표창곡예\' 표식이 남으면 아칼리가 돌진하니, 그 타이밍에 (E)\'경멸\'로 쳐내어 뒤로 던지세요. 둔화된 아칼리에게 (W)\'심판의 원\'을 켜서 화력을 집중하면 딜교환에서 앞설 수 있어요.', lv6: '(R)\'불사의 공포\'를 맞힌 뒤 아칼리의 체력이 낮아지면 재사용해 처형하세요. 아칼리가 (R)\'무결처형\'으로 도약해 들어오면 당황하지 말고 (E)\'경멸\'로 기절시켜 뒤로 던지거나 거리를 벌리세요. (R)\'불사의 공포\'는 대상 지정 스킬이 아니라 (W)\'황혼의 장막\' 속 아칼리에게도 맞힐 수 있지만, 위치를 보기 어려우니 모습이 드러날 때 쓰세요.', item: '맬모셔스의 아귀를 가서 아칼리의 폭발적인 마법 피해를 생명선 보호막으로 버티세요. 신발은 마법 저항력을 높이고 군중 제어 지속시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 순간이동을 추천해요. 아칼리의 높은 기동성에 대응해 빠르게 합류하거나 라인 복귀를 하세요.' },
    '아크샨': { lv1: '아크샨이 (Q)\'복수의 부메랑\'으로 원거리에서 견제하므로 미니언을 끼고 파밍하며 거리를 조절하세요. (Q)\'부식성 폭약\'을 적중시켜 둔화를 걸면 접근하기가 한결 수월해져요. 초반에는 무리하게 싸우기보다 성장에 집중하며 다음 단계를 준비해요.', lv3: '아크샨이 (E)\'영웅의 비상\'으로 빠르게 접근하면 (E)\'경멸\'을 사용하여 적을 내 뒤로 던지세요. (Q)\'부식성 폭약\'으로 둔화를 걸고 (W)\'심판의 원\'을 사용하면 안정적으로 피해를 줄 수 있어요. 아크샨의 (P)\'비열한 싸움\'으로 인한 추가 피해를 조심하며 딜교환을 진행해요.', lv6: '아크샨의 체력이 낮을 때 (R)\'불사의 공포\'를 사용하여 처형을 노리는 것이 좋아요. 아크샨이 (R)\'인과응보\'를 사용하여 큰 피해를 줄 수 있으니 체력 관리에 유의하세요. 라인을 당겨 정글러의 개입에 대비하며 위치를 지키세요.', item: '판금 장화와 삼위일체. 아크샨의 기본 공격 피해를 줄이고 스킬 가속을 높이기 위해서예요.', spell: '점멸과 점화. 아크샨을 빠르게 마무리하기 위해서예요.' },
    '아트록스': { lv1: '아트록스는 (Q)\'다르킨의 검\'의 끝자락을 맞히면 에어본과 큰 피해를 주니 주의하세요. 1~2레벨에는 (Q)\'부식성 폭약\'을 맞춰 둔화시킨 뒤 (W)\'심판의 원\'으로 짧게 교환하며 버티세요. 검의 범위가 바뀌는 동작을 보고 옆으로 움직여 초기 압박을 견뎌내세요.', lv3: '아트록스가 (W)\'지옥사슬\'을 쓰면 중앙으로 끌려가지 않게 빠르게 범위를 벗어나세요. (E)\'파멸의 돌진\'이 빠진 틈을 타서 (Q)\'부식성 폭약\'을 맞히고 (W)\'심판의 원\'으로 몰아치세요. (E)\'경멸\'로 아트록스를 던져서 공격 흐름을 끊는 것이 중요해요.', lv6: '아트록스가 (R)\'세계의 종결자\'를 켜면 회복량이 늘어나니 무리하게 싸우지 마세요. 상대 체력이 낮을 때 (R)\'불사의 공포\'를 사용하여 처형을 노리세요. 라인을 관리하며 정글러를 불러 아트록스를 압박하는 구도를 만드세요.', item: '첫 코어 아이템으로 굶주린 히드라를 올려 공격력과 생명력 흡수를 확보하세요. 신발은 아트록스의 물리 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 아트록스의 (P)\'사신 태세\'와 (E)\'파멸의 돌진\' 회복을 줄이세요.' },
    '암베사': { lv1: '암베사는 (P)\'용사냥개의 발걸음\'으로 스킬 사용 후 짧게 돌진하며 강한 평타를 날리니 너무 가까이 붙지 마세요. (Q)\'부식성 폭약\'으로 둔화를 걸어 거리를 유지하고, (Q)\'교활한 휩쓸기\'의 바깥 날 범위에 맞지 않게 주의하며 견제하세요. 상대가 돌진으로 들어오는 타이밍에 맞춰 발밑에 스킬을 쓰면 추격 속도를 늦출 수 있어요.', lv3: '암베사가 (W)\'배척\'으로 보호막을 켜고 준비할 때는 딜교환을 멈춰서 피해량이 증가하는 것을 막으세요. (E)\'찢어 가르기\'로 둔화가 걸렸을 때 (E)\'경멸\'로 기절시켜 뒤로 던지면 상대의 진입 흐름을 끊을 수 있어요. 상대를 뒤로 던진 직후에 (W)\'심판의 원\'을 켜서 표식이 남은 암베사에게 빠르게 피해를 입히세요.', lv6: '(R)\'공개 처형\'은 일직선상에서 가장 멀리 있는 적에게 순간이동해 제압하니, 궁극기가 남아 있을 때는 체력을 넉넉히 유지하세요. (R)\'불사의 공포\'를 맞힌 뒤 체력이 낮아진 암베사를 제압해 처형하고 주변 적에게 공포를 거세요. 암베사가 궁극기를 쓰기 전에 (E)\'경멸\'로 기절시켜 각을 지우거나 정글러의 백업을 기다리며 라인을 관리하세요.', item: '삼위일체를 첫 코어로 가서 공격력과 체력 그리고 공격 속도를 보충하세요. 신발은 암베사의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 암베사의 기동성이 좋으므로 점화의 추가 피해로 킬각을 빠르게 잡는 것이 중요해요.' },
    '애니비아': { lv1: '애니비아는 (Q)\'냉기 폭발\'로 멀리서 기절을 걸고 냉각을 시켜 견제해요. (Q)\'부식성 폭약\'을 맞춰 애니비아의 움직임을 둔화시킨 뒤 평타로 대응하며 거리를 좁히세요. 구체가 폭발하기 전에 옆으로 비켜 걸으며 다가가면 접근하기 수월해요.', lv3: '애니비아가 (E)\'동상\'을 사용하기 전에 (E)\'경멸\'로 빠르게 파고들어 기절을 시키세요. (W)\'결정화\' 벽이 세워지면 이동 경로가 막히니 벽이 생성되기 전에 (Q)\'부식성 폭약\'을 사용하여 접근하세요. 애니비아가 (Q)\'냉기 폭발\'을 사용하여 적을 냉각시킨 직후에는 교환을 피하세요.', lv6: '애니비아의 (R)\'얼음 폭풍\' 안에서는 둔화가 심하니 장판 밖에서 (E)\'경멸\'로 진입하세요. 체력이 낮은 애니비아는 (R)\'불사의 공포\'로 처형할 수 있지만, (P)\'환생\'으로 알이 되어 체력을 회복할 수 있으니 주의하세요. 애니비아가 (W)\'결정화\'로 도주로를 차단하기 전에 정글러와 함께 압박하세요.', item: '굶주린 히드라와 헤르메스의 발걸음을 선택하세요. 헤르메스의 발걸음으로 애니비아의 마법 피해를 견디고 굶주린 히드라로 생명력 흡수를 챙기세요.', spell: '점멸과 점화를 추천해요. 점화로 애니비아의 체력을 깎아 (R)\'불사의 공포\'로 확실하게 마무리하세요.' },
    '야스오': { lv1: '야스오가 (Q)\'강철 폭풍\'으로 견제하며 미니언을 타고 들어올 때 (Q)\'부식성 폭약\'을 맞춰 둔화를 걸어주세요. (P)\'낭인의 길\' 보호막이 켜져 있을 때는 딜교환 효율이 낮으니 평타와 (P)\'화염의 메아리\'로 보호막을 먼저 빼는 게 좋아요. 무리하게 들어가기보다 사거리를 조절하며 야스오의 (Q)\'강철 폭풍\' 중첩을 확인하세요.', lv3: '야스오가 (W)\'바람 장막\'을 켜면 (Q)\'부식성 폭약\'이 막히니 벽이 사라질 때까지 기다려야 해요. 야스오가 (E)\'질풍검\'으로 들어오면 (E)\'경멸\'로 기절을 시키고 뒤로 던진 뒤 (W)\'심판의 원\'으로 몰아붙여요. 야스오의 (Q)\'강철 폭풍\' 회오리가 날아오는 타이밍에는 (E)\'경멸\'로 거리를 조절하거나 기절로 흐름을 끊어주세요.', lv6: '야스오가 (Q)\'강철 폭풍\'으로 띄워 올리면 (R)\'최후의 숨결\'에 노출될 수 있으니 주의해야 해요. 야스오의 체력이 낮을 때 (R)\'불사의 공포\'를 사용해 처형하면 되는데, (E)\'질풍검\'으로 도망갈 경로를 차단하는 게 중요해요. 라인을 너무 밀어두면 야스오가 (E)\'질풍검\'으로 미니언을 타고 복귀하기 쉬우니 적절히 관리하세요.', item: '첫 코어 아이템으로 갈라진 하늘을 올려 전투 지속력을 높여주세요. 신발은 야스오의 기본 공격 피해를 줄여주는 판금 장화를 추천해요.', spell: '점멸과 점화를 선택하세요. 점화의 마무리 피해로 낮은 체력의 야스오를 (R)\'불사의 공포\' 처형 범위까지 빠르게 깎을 수 있어요.' },
    '오공': { lv1: '오공은 (Q)\'파쇄격\'으로 사거리가 늘어난 평타를 쓰고 (P)\'바위 피부\' 덕분에 싸울수록 단단해져요. 1~2레벨에는 (Q)\'부식성 폭약\'으로 오공을 둔화시키며 체력을 깎고 거리를 유지하세요. 오공의 (Q)\'파쇄격\'을 맞으면 방어력이 낮아지니 주의해야 해요.', lv3: '오공이 (W)\'분신 전사\'를 사용해 투명해지면 진짜 위치를 파악하는 것이 중요해요. 오공이 (E)\'근두운 급습\'으로 들어올 때 (E)\'경멸\'을 사용하여 오공을 뒤로 던지고 기절시키세요. 오공의 (W)\'분신 전사\'가 빠진 타이밍에 (W)\'심판의 원\'으로 지속적인 피해를 입히며 싸우세요.', lv6: '오공의 (R)\'회전격\'에 맞으면 공중에 떠서 스킬을 쓸 수 없으니 (R)\'회전격\'을 쓰는 오공에게는 붙지 마세요. 오공의 체력이 낮아지면 (R)\'불사의 공포\'로 처형을 노려보세요. (R)\'회전격\'이 끝난 직후에는 (E)\'경멸\'로 진입하거나 거리를 벌리며 대응하세요.', item: '첫 코어로 갈라진 하늘을 선택해 전투 지속력을 높이세요. 신발은 오공의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. (R)\'불사의 공포\'로 적을 처형할 때 점화의 피해를 더해 확실하게 킬을 노리세요.' },
    '오로라': { lv1: '오로라는 (Q)\'이중 저주\'를 사용해 멀리서 견제하며 (P)\'영혼 방호술\'로 체력을 회복해요. (Q)\'이중 저주\'의 저주가 되돌아오는 경로를 피해 위치를 잡고 (Q)\'부식성 폭약\'을 맞춰 둔화를 거세요. 1~2레벨 구간은 오로라의 견제가 강하니 거리를 조절하며 미니언을 받아내세요.', lv3: '오로라가 (E)\'마법의 문\'을 사용해 둔화를 걸고 뒤로 도약하면 무리하게 쫓지 마세요. 오로라의 (E)\'마법의 문\'이 빠진 것을 확인한 뒤 (E)\'경멸\'로 돌진하여 기절을 시키고 (W)\'심판의 원\'을 사용하세요. 오로라가 (W)\'장막 너머로\'로 투명해지면 위치를 주의 깊게 살피며 대응해요.', lv6: '오로라가 (R)\'세계의 경계\'를 사용하여 영역을 만들면 그 안에서 싸우는 것을 주의하세요. 오로라의 체력이 일정 수준 이하일 때 (R)\'불사의 공포\'로 제압하여 확실하게 처치하세요. 오로라가 (W)\'장막 너머로\'를 써서 도망치려 할 때 (E)\'경멸\'을 사용하여 거리를 좁히세요.', item: '삼위일체와 헤르메스의 발걸음을 추천해요. 삼위일체로 전투 지속력을 높이고 헤르메스의 발걸음으로 오로라의 마법 피해를 줄이세요.', spell: '점멸과 점화를 추천해요. (R)\'불사의 공포\'로 적을 제압할 때 점화로 마무리 피해를 입혀 오로라의 체력 회복을 억제하세요.' },
    '오른': { lv1: '오른은 (P)\'간이 대장간\' 때문에 초반 방어력과 마법 저항력이 높아요. (Q)\'용암 균열\'로 생기는 용암 기둥 위치를 보고 피하면서 (Q)\'부식성 폭약\'으로 둔화를 걸어 견제하세요.', lv3: '오른의 (E)\'화염 돌진\'이 벽에 부딪히면 공중으로 띄우니 벽 근처에서는 조심해야 해요. (W)\'불꽃 풀무질\'을 맞고 불안정 상태가 되면 이동 불가 효과가 길어지니 주의하고, (E)\'경멸\'로 진입하며 (W)\'심판의 원\'을 사용하세요.', lv6: '오른의 (R)\'대장장이 신의 부름\'에 맞으면 공중으로 띄워지니 주의하세요. 공중으로 띄워지는 상황을 피하고 상대 체력이 낮을 때 (R)\'불사의 공포\'를 사용해 처형을 노려보세요.', item: '칠흑의 양날 도끼를 첫 코어로 가고 신발은 판금 장화로 선택하세요. 칠흑의 양날 도끼로 단단한 오른의 방어력을 깎고 판금 장화로 오른의 기본 공격 피해를 줄여요.', spell: '점멸과 점화를 추천해요. 오른은 (P)\'간이 대장간\'으로 단단하니 점화의 고정 피해로 (R)\'불사의 공포\' 처형 범위까지 깎기 좋아요.' },
    '올라프': { lv1: '올라프가 (Q)\'역류\'를 던져 방어력을 낮추고 접근할 때 (Q)\'부식성 폭약\'을 맞춰 거리를 조절하세요. 1~2레벨 구간에서는 올라프의 평타가 강하니 (W)\'심판의 원\'으로 짧게 견제하고 무리하게 붙지 마세요.', lv3: '올라프가 (W)\'버티기\'를 사용해 보호막을 얻으면 무리하게 들어가지 마세요. (Q)\'부식성 폭약\'으로 둔화를 걸고 (W)\'심판의 원\'을 사용해 딜을 넣다가, 올라프가 (Q)\'역류\'를 다시 주우러 갈 때 (E)\'경멸\'로 진입을 끊어내세요.', lv6: '올라프가 (R)\'라그나로크\'를 켜면 이동 방해 효과가 통하지 않으니 (E)\'경멸\'로 기절을 시도하지 마세요. (R)\'불사의 공포\'로 낮은 체력의 올라프를 처형할 수 있지만, 궁극기 사용 중에는 정면 싸움을 피하며 라인을 관리하세요.', item: '판금 장화를 구매하여 올라프의 기본 공격 피해를 줄이세요. 첫 코어 아이템으로는 거대한 히드라를 선택해 체력과 공격력을 챙기세요.', spell: '점멸과 점화를 추천해요. 점화의 회복 감소로 올라프의 (P)\'광전사의 분노\' 생명력 흡수를 줄이세요.' },
    '요네': { lv1: '요네는 (Q)\'필멸의 검\'을 내질러 견제하고 (P)\'사냥꾼의 길\'로 두 번째 공격마다 마법 피해를 입혀요. (Q)\'부식성 폭약\'을 맞춰 요네를 둔화시키며 거리 조절을 하세요. 평타 맞교환은 짧게 끝내고 요네의 다음 공격 타이밍을 피하는 것이 중요해요.', lv3: '(E)\'영혼해방\'을 사용한 요네는 나중에 육신으로 돌아오니 무작정 쫓지 말고 위치를 잡으세요. 요네가 (W)\'영혼 가르기\'로 보호막을 얻기 전에 (E)\'경멸\'로 기절시켜 뒤로 던지면 효율적이에요. (Q)\'부식성 폭약\'으로 둔화시킨 뒤 (W)\'심판의 원\'을 켜서 빠르게 피해를 누적하세요.', lv6: '요네의 (R)\'운명봉인\'에 맞으면 끌려가 공중에 뜨고 스킬을 쓸 수 없으니, 일직선 경로에서 벗어나도록 거리를 조절하세요. 요네의 체력이 일정 수준 이하로 떨어지면 (R)\'불사의 공포\'를 사용해 확실하게 처형하세요. (E)\'영혼해방\'이 끝나면 요네가 육신 자리로 돌아오니 그 위치에 (Q)\'부식성 폭약\'을 맞히면 킬각을 잡기 편해요.', item: '삼위일체를 첫 코어로 가서 공격 속도와 체력을 보충해 지속 전투력을 높이세요. 신발은 요네의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화의 강력한 고정 피해를 더해 (R)\'불사의 공포\' 처형 범위를 빠르게 만들 수 있어요.' },
    '요릭': { lv1: '요릭이 (Q)\'최후의 의식\'으로 미니언을 막타 쳐서 무덤을 생성하는 것을 방해하세요. (Q)\'부식성 폭약\'을 사용하여 요릭에게 둔화를 걸고 거리를 조절하며 미니언과 함께 압박하세요. 무덤이 쌓이기 전에 짧게 교환하여 요릭의 회복력을 낮추는 것이 좋아요.', lv3: '요릭이 (E)\'애도의 안개\'를 던져 표식을 남기면 망령이 달려드니 (E)\'경멸\'로 요릭을 뒤로 던져 거리를 확보하세요. (W)\'망자의 진\' 벽에 갇히지 않도록 주의하며 (Q)\'부식성 폭약\'으로 요릭의 움직임을 둔화시키세요. (W)\'심판의 원\'을 켠 상태에서 요릭의 스킬이 빠진 타이밍에 진입하는 것이 효과적이에요.', lv6: '요릭이 (R)\'군도의 장송곡\'으로 안개 마녀를 소환하면 소환물들의 공격이 매우 강력해지니 주의하세요. 요릭의 체력이 낮아지면 (R)\'불사의 공포\'로 빠르게 처형하여 승부를 보세요. 라인을 빠르게 밀어 넣고 요릭이 소환물에 집중할 때 정글러의 개입을 유도하세요.', item: '삼위일체를 첫 코어로 올려 전투 능력을 높이세요. 신발은 요릭의 물리 피해를 줄이기 위해 판금 장화를 선택하세요.', spell: '점멸과 점화를 추천해요. 요릭이 (Q)\'최후의 의식\'으로 체력을 회복하는 것을 점화로 억제하며 마무리하세요.' },
    '우디르': { lv1: '우디르는 (E)\'불길 쇄도\' 태세로 빠르게 접근해 첫 평타로 기절시키려 해요. (Q)\'부식성 폭약\'을 맞혀 둔화시켜 접근을 늦추고 거리 조절을 하세요. 우디르가 기절 평타를 쓰기 전에 뒤로 물러나며 평타 견제를 하세요.', lv3: '우디르가 (Q)\'야생 발톱\' 태세로 들어오면 (Q)\'부식성 폭약\'을 맞힌 뒤 (W)\'심판의 원\'으로 화력을 쏟으세요. (W)\'강철 갑옷\'의 보호막과 회복이 작동하는 동안에는 딜교환을 짧게 가져가고 보호막이 빠진 뒤에 공격하세요. (E)\'불길 쇄도\'의 기절 평타는 맞으면 스킬을 쓸 수 없으니 붙기 전에 (E)\'경멸\'로 먼저 진입하거나 거리를 벌려 흐름을 끊으세요.', lv6: '(R)\'날개 돋친 폭풍\'을 켠 우디르는 주변에 지속 피해와 둔화를 주니 너무 오래 붙어 있지 마세요. 우디르가 (E)\'불길 쇄도\'를 재사용해 이동 불가 효과에 면역이 되면 (E)\'경멸\'의 기절이 통하지 않으니 그동안은 기절을 노리지 마세요. 체력이 낮아진 우디르에게 (R)\'불사의 공포\'를 맞히고 처형 각을 잡아 마무리하세요.', item: '삼위일체와 판금 장화를 추천해요. 삼위일체로 공격력과 체력을 보충하고, 판금 장화로 (Q)\'야생 발톱\'의 기본 공격 피해를 줄이세요.', spell: '점멸과 점화를 추천해요. (W)\'강철 갑옷\'을 통한 우디르의 체력 회복을 억제해 킬각을 잡으세요.' },
    '워윅': { lv1: '워윅은 (Q)\'야수의 송곳니\'를 사용해 도약하며 체력을 회복하니 1~2레벨에 무리하게 맞붙지 마세요. (Q)\'부식성 폭약\'으로 워윅의 접근을 늦추며 거리를 조절하고 미니언을 먼저 챙기세요. 워윅이 체력이 낮아지면 (P)\'끝없는 허기\'로 회복이 늘어나니 주의하며 대응하세요.', lv3: '워윅의 (E)\'원시의 포효\'가 빠진 것을 확인한 뒤에 (E)\'경멸\'을 사용하여 딜교환을 시도하세요. 워윅의 (Q)\'야수의 송곳니\'를 피한 뒤 (E)\'경멸\'로 적을 뒤로 던지며 (W)\'심판의 원\'을 사용하면 좋아요. 내 체력이 절반 아래로 내려가면 워윅이 (W)\'피의 사냥\'으로 빨라지니 체력 관리에 주의해야 해요.', lv6: '워윅의 (R)\'무한의 구속\'은 대상을 제압하므로 제압 중에는 (R)\'불사의 공포\'나 (E)\'경멸\'을 사용할 수 없음을 명심하세요. 내 체력이 낮아지면 워윅이 (W)\'피의 사냥\'으로 빠르게 접근할 수 있으니 라인을 당겨 관리하며 정글러를 부르세요. (R)\'불사의 공포\'를 활용해 워윅의 체력이 낮아졌을 때 처형하는 구도를 만드세요.', item: '삼위일체와 헤르메스의 발걸음을 가세요. 워윅의 마법 피해를 견디고 CC 지속 시간을 줄이는 것이 중요해요.', spell: '점멸과 점화를 추천해요. 점화로 워윅의 (Q)\'야수의 송곳니\'에 의한 체력 회복을 억제하세요.' },
    '이렐리아': { lv1: '1~2레벨에는 이렐리아가 (Q)\'칼날 쇄도\'로 미니언을 타고 들어오며 체력을 회복하니 거리를 유지하세요. (Q)\'부식성 폭약\'을 적중시켜 둔화시킨 뒤 평타로 대응하고, 미니언 체력이 낮은 쪽에 서 있지 않도록 주의하세요. (P)\'아이오니아의 열정\' 중첩이 쌓이기 전에 짧게 딜교환하고 빠지세요.', lv3: '(E)\'쌍검협무\'의 두 칼날이 만나는 길목을 피해 기절을 피하고 표식이 남지 않게 하세요. 이렐리아가 (Q)\'칼날 쇄도\'로 진입하는 타이밍에 (E)\'경멸\'을 사용해 뒤로 던지면 진입 흐름을 완전히 끊을 수 있어요. (W)\'저항의 춤\' 충전 중에는 물리 피해가 감소하니 충전이 끝난 뒤에 (W)\'심판의 원\'을 켜서 공격하세요.', lv6: '(R)\'선봉진격검\'의 결계 안에서는 둔화되며 피해를 입으니 빠르게 벗어나세요. 상대 체력이 일정 수준 이하로 떨어졌을 때 (R)\'불사의 공포\'를 사용해 제압하고 처형하며 주변 적에게 공포를 거세요. 미니언이 많은 곳에서는 (Q)\'칼날 쇄도\'가 쉽게 초기화되니 웨이브를 너무 밀어넣지 말고 싸우세요.', item: '삼위일체와 판금 장화를 추천해요. 삼위일체로 공격력과 체력을 보강하고, 판금 장화로 이렐리아의 기본 공격 피해를 줄이세요.', spell: '점멸과 점화를 추천해요. 점화로 (Q)\'칼날 쇄도\'의 체력 회복 효과를 줄여서 처형 각을 더 쉽게 잡으세요.' },
    '일라오이': { lv1: '일라오이는 (P)\'고대신의 예언자\'로 벽 근처에서 촉수를 소환하니 지형에서 떨어진 중앙에서 싸우세요. (Q)\'부식성 폭약\'을 맞춰 둔화시킨 뒤 거리 조절을 하며 일라오이가 (Q)\'촉수 강타\'로 공격하지 못하게 하세요. 첫 웨이브는 무리하지 말고 받아먹으세요.', lv3: '(E)\'영혼의 시험\'에 맞으면 영혼이 분리되는데, 영혼에서 너무 멀어지면 숙주가 되어 촉수가 소환되니 적당한 거리를 유지하세요. 일라오이가 (W)\'혹독한 가르침\'으로 진입할 때 (E)\'경멸\'로 기절시켜 뒤로 던지고 촉수가 없는 곳으로 위치를 옮기세요. (Q)\'부식성 폭약\'으로 표식을 남긴 뒤 (W)\'심판의 원\'을 켜서 피해를 입히세요.', lv6: '일라오이가 (R)\'믿음의 도약\'을 사용하면 즉시 그 범위를 벗어나 촉수 공격을 피하세요. (R)\'불사의 공포\'를 맞혀 둔화시킨 뒤 체력이 낮아졌을 때 처형하여 주변 적을 공포에 빠뜨리세요. 정글러가 올 때까지 라인을 당겨서 벽 근처에서의 교전을 피하세요.', item: '삼위일체와 판금 장화를 추천해요. 삼위일체로 공격력과 체력을 챙기고 판금 장화의 효과로 일라오이의 기본 공격 피해를 줄이세요.', spell: '점멸과 순간이동을 추천해요. 라인전 도중 (E)\'영혼의 시험\' 사거리에서 벗어나기 위해 점멸이 필요하고, 순간이동으로 라인 손실을 줄이세요.' },
    '자크': { lv1: '자크는 (Q)\'탄성 주먹\'으로 팔을 뻗어 견제하고 (P)\'세포 분열\' 조각을 흡수해 체력을 회복해요. (Q)\'부식성 폭약\'을 적중시켜 둔화시킨 뒤 거리를 유지하며 미니언과 함께 딜교환하세요. 조각 근처에서 싸우면 자크가 체력을 쉽게 회복하니 조각에서 멀리 떨어진 위치를 잡으세요.', lv3: '자크가 (E)\'새총 발사\'로 날아와 맞히면 공중에 뜨는 동안 스킬을 쓸 수 없으니, 충전하는 모습이 보이면 착지 지점에서 벗어나세요. (W)\'불안정 물질\'은 최대 체력 비례 피해를 주니 붙으면 오래 버티지 말고 (Q)\'부식성 폭약\'으로 둔화를 걸며 거리를 조절하세요. (Q)\'부식성 폭약\'을 먼저 맞히고 (W)\'심판의 원\'으로 표식이 남은 자크에게 화력을 집중하세요.', lv6: '자크가 (R)\'바운스!\'로 튀어 오를 때 맞아 공중에 뜨면 스킬을 쓸 수 없으니 착지 범위에서 벗어나세요. 체력이 낮은 자크에게 (R)\'불사의 공포\'를 맞혀 처형을 노리세요. 자크가 (P)\'세포 분열\'로 갈라지면 조각을 빠르게 정리해 부활하지 못하게 하세요.', item: '칠흑의 양날 도끼를 가서 체력이 높은 자크의 방어력을 깎고 체력과 스킬 가속 효율을 챙기세요. 신발은 자크의 마법 피해를 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과로 (P)\'세포 분열\'을 통한 자크의 체력 회복을 억제하세요.' },
    '자헨': { lv1: '1~2레벨에는 자헨이 (Q)\'다르킨의 글레이브\'로 연속 공격하며 체력을 회복하니 주의하세요. (Q)\'부식성 폭약\'을 사용하여 자헨에게 둔화를 걸고 거리를 유지하며 파밍하세요. 자헨이 (P)\'전쟁 단련\' 중첩을 쌓지 못하게 짧게 교환하세요.', lv3: '자헨이 (W)\'공포의 귀환\'으로 끌어당기려 하면 (E)\'경멸\'을 사용하여 자헨을 기절시키고 뒤로 넘기세요. 자헨이 (E)\'찬란한 쇄도\'로 돌진할 때 (Q)\'부식성 폭약\'을 맞히면 추격이 쉬워져요. 자헨의 (Q)\'다르킨의 글레이브\' 재사용을 피하며 (W)\'심판의 원\'으로 압박하세요.', lv6: '자헨이 (R)\'단호한 판결\'로 내려찍는 동안은 받는 피해가 줄고 입힌 피해만큼 회복하니 그 사이에는 무리하게 딜을 넣지 마세요. 자헨의 체력이 낮을 때 (R)\'불사의 공포\'로 처형을 노리되, (P)\'전쟁 단련\' 중첩이 가득 차면 부활할 수 있으니 확실히 처치해야 해요.', item: '첫 코어 아이템으로 굶주린 히드라를 선택하여 전투 지속력을 높이세요. 신발은 자헨의 물리 피해를 줄여 주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 자헨은 (Q)\'다르킨의 글레이브\'와 (R)\'단호한 판결\'로 체력을 회복하니 점화로 회복을 줄이세요.' },
    '잭스': { lv1: '잭스가 (Q)\'도약 공격\'으로 붙기 전에 (Q)\'부식성 폭약\'을 맞혀 둔화를 걸고 거리를 유지하세요. 1~2레벨에는 잭스의 (W)\'무기 강화\' 평타 한 방이 매우 아프니 무리하게 평타를 섞지 말고 스킬로만 견제해요. (P)\'가차없는 맹공\'으로 공격 속도가 오르기 전에 짧게 딜교환하고 빠지는 것이 중요해요.', lv3: '잭스가 (E)\'반격\'을 켜면 기본 공격을 모두 피하고 끝나면 기절을 걸어 오니, (W)\'심판의 원\' 사격을 멈추고 끝나기 전에 거리를 벌리세요. 잭스가 (Q)\'도약 공격\'으로 진입한 직후에 (E)\'경멸\'로 먼저 기절을 걸면 흐름을 끊을 수 있어요. (Q)\'부식성 폭약\'을 먼저 맞혀야 (W)\'심판의 원\'이 표식이 남은 잭스를 우선 공격해 효율적인 딜교환이 가능해요.', lv6: '잭스가 (R)\'무기의 달인\'을 사용해 방어력과 마법 저항력을 높인 상태에서는 정면 승부를 피하고 시간을 끄세요. 잭스의 체력이 낮아졌을 때 (R)\'불사의 공포\'를 맞혀 둔화시키고 처형 가능 체력까지 깎아 마무리하세요. (E)\'경멸\'로 잭스를 기절시켜 정글러가 개입할 시간을 만들거나 포탑 쪽으로 유인해 킬각을 잡으세요.', item: '삼위일체를 첫 코어로 가서 공격력과 체력 그리고 공격 속도를 모두 챙기세요. 신발은 잭스의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 잭스의 체력을 빠르게 깎아 (R)\'불사의 공포\' 처형 각을 잡기 수월해요.' },
    '제이스': { lv1: '제이스가 캐논 형태로 (Q)\'전격 폭발\'을 멀리서 쏘며 견제할 때 직선 밖에서 거리 조절을 하세요. (Q)\'부식성 폭약\'을 던져 제이스의 접근을 늦추며 미니언을 챙기세요. 제이스가 해머의 (Q)\'하늘로!\'로 도약하며 들어오기 전까지는 사거리를 유지하세요.', lv3: '제이스의 (E)\'천둥 강타\'를 미리 유도하여 뺀 뒤에 (E)\'경멸\'로 돌진하여 충돌하며 딜교환을 시작하세요. (Q)\'부식성 폭약\'을 맞힌 뒤 (W)\'심판의 원\'을 사용하면 제이스가 형태를 바꿔 도망치기 어려워요. 제이스가 (E)\'가속 관문\'을 통해 (Q)\'전격 폭발\'을 강화해서 쏘면 즉시 옆으로 피하세요.', lv6: '제이스의 체력이 일정 수준 이하로 떨어지면 (R)\'불사의 공포\'를 사용하여 제압하고 처형을 시도하세요. 제이스가 (R)\'머큐리 해머\'로 변환하여 방어력을 높이기 전에 빠르게 진입하는 것이 중요해요. 제이스가 (Q)\'전격 폭발\'로 멀리서 저항하려 하면 (E)\'경멸\'로 거리를 좁히며 싸우세요.', item: '갈라진 하늘을 첫 코어로 올려 전투 지속력을 높이세요. 신발은 제이스의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 제이스의 체력이 낮을 때 점화를 사용하여 확실하게 킬을 가져오세요.' },
    '초가스': { lv1: '초가스는 (Q)\'파열\'로 적을 공중에 띄워 피해와 둔화를 주니, 지면 표시가 보이면 즉시 범위 밖으로 피하세요. (E)\'날카로운 가시\'를 켜면 다음 세 번의 평타마다 정면으로 가시가 나가 둔화를 주니 초가스의 정면에서 너무 오래 싸우지 마세요. (Q)\'부식성 폭약\'을 적중시켜 초가스의 접근을 늦추며 체력을 깎으세요.', lv3: '(W)\'흉포한 울부짖음\'에 침묵되면 스킬을 쓸 수 없으니 초가스가 먼저 비명을 지른 뒤에 진입하세요. (Q)\'파열\'을 피한 직후 (E)\'경멸\'로 돌진해 보호막을 얻으며 초가스를 뒤로 던지세요. 이후 (Q)\'부식성 폭약\'을 맞히고 (W)\'심판의 원\'을 켜서 빠르게 피해를 입히세요.', lv6: '(R)\'포식\'은 방어력을 무시하는 큰 고정 피해를 입히니, 체력이 낮을 때는 초가스와 거리를 유지하세요. 초가스의 체력이 일정 수준 이하로 떨어지면 (R)\'불사의 공포\'를 꽂고 처형 각을 보세요. (Q)\'파열\'에 공중으로 띄워지면 스킬을 쓸 수 없으니, 상대의 핵심 스킬이 빠진 것을 확인하고 진입하세요.', item: '칠흑의 양날 도끼를 가서 체력을 높이고 방어력 감소 효과로 초가스를 더 효과적으로 공격하세요. 신발은 초가스의 마법 피해를 줄이고 (W)\'흉포한 울부짖음\'의 침묵 지속 시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 (P)\'육식\'의 체력 회복 효과를 줄이세요.' },
    '카밀': { lv1: '카밀은 (Q)\'정확성 프로토콜\'의 두 번째 강화 평타가 매우 강력하니 이를 피하는 것이 중요해요. (Q)\'부식성 폭약\'을 적중시켜 둔화시킨 뒤 거리 조절을 하며 견제하세요. (P)\'적응형 방어 체계\' 보호막이 활성화된 상태에서 무리하게 평타를 주고받지 마세요.', lv3: '(E)\'갈고리 발사\'로 진입하는 카밀을 (E)\'경멸\'로 쳐내어 위치를 바꾸면 딜교환을 주도할 수 있어요. (W)\'전술적 휩쓸기\'의 바깥쪽 절반에 맞으면 둔화되고 상대가 회복하니 최대한 안쪽으로 파고드세요. (Q)\'부식성 폭약\'으로 표식을 남긴 후 (W)\'심판의 원\'을 켜서 빠르게 피해를 입히세요.', lv6: '(R)\'마법공학 최후통첩\'에 갇히면 탈출할 수 없으니 최대한 버티며 상대의 공격을 받아내세요. 상대 체력이 낮아졌을 때 (R)\'불사의 공포\'를 사용해 제압하고 처형하며 주변 적에게 공포를 거세요. 카밀이 (E)\'갈고리 발사\'로 벽을 넘어 정글러와 함께 덮칠 수 있으니 항상 시야를 확인하세요.', item: '삼위일체와 판금 장화를 추천해요. 판금 장화는 카밀의 기본 공격 피해를 줄여주며 삼위일체는 공격력과 체력을 보완해줘요.', spell: '점멸과 점화를 추천해요. 카밀이 (W)\'전술적 휩쓸기\'로 체력을 회복하는 것을 점화의 치유 감소로 억제하세요.' },
    '카사딘': { lv1: '1~2레벨 구간에는 카사딘의 (Q)\'무의 구체\'로 인한 보호막과 견제를 조심해야 해요. (Q)\'부식성 폭약\'을 사용하여 카사딘이 다가오지 못하게 둔화를 걸고 거리를 유지하세요. 미니언을 먹으면서 카사딘의 마나 소모를 유도하는 것이 좋아요.', lv3: '3레벨이 되면 (E)\'경멸\'을 사용하여 카사딘을 뒤로 던지고 (W)\'심판의 원\'으로 지속 피해를 입히세요. 카사딘의 (E)\'힘의 파동\'을 맞기 전에 (Q)\'부식성 폭약\'을 먼저 맞춰서 이동 속도를 늦추는 것이 중요해요. 카사딘의 (Q)\'무의 구체\' 보호막이 빠진 타이밍에 딜교환을 시작하세요.', lv6: '6레벨 이후에는 카사딘이 (R)\'균열 이동\'으로 도망치려 할 때 (R)\'불사의 공포\'로 체력이 낮은 상태를 확인하고 처형을 시도하세요. 카사딘의 순간이동을 주의하며 라인을 당겨서 정글러의 도움을 받기 편한 구도로 만드세요. 카사딘의 체력이 일정 수준 이하일 때 (R)\'불사의 공포\'를 신중하게 사용해야 해요.', item: '갈라진 하늘과 헤르메스의 발걸음을 추천해요. 카사딘의 마법 피해를 견디기 위해 헤르메스의 발걸음을 사고, 전투 지속력을 위해 갈라진 하늘을 가요.', spell: '점멸과 점화를 추천해요. 카사딘을 확실하게 마무리하기 위해서예요.' },
    '카시오페아': { lv1: '카시오페아의 (Q)\'맹독 폭발\' 견제가 들어올 때 무리하게 다가가지 마세요. (Q)\'부식성 폭약\'을 사용해 적에게 둔화를 걸며 미니언과 함께 거리를 조절하며 차근차근 성장해요.', lv3: '(E)\'경멸\'을 적중시켜 기절시킨 뒤 (W)\'심판의 원\'으로 딜교환을 시도해요. 카시오페아가 (W)\'독기의 늪\'을 깔면 진입하기 어려우니 그 스킬이 빠진 것을 확인하고 들어가세요.', lv6: '체력이 낮아진 상대에게 (R)\'불사의 공포\'를 사용해 처형 각을 보세요. (R)\'석화의 응시\'를 등지고 있어야 기절을 피할 수 있으니 전투 중 위치 선정이 매우 중요해요.', item: '헤르메스의 발걸음과 갈라진 하늘을 가요. 마법 저항력과 강인함을 얻기 위해 헤르메스의 발걸음을 선택해요. 갈라진 하늘은 전투를 도와줘요.', spell: '점멸과 점화. 카시오페아가 (E)\'쌍독니\'로 체력을 회복하는 것을 막기 위해 점화를 선택해요.' },
    '케넨': { lv1: '케넨은 (Q)\'천둥의 표창\'을 던져 (P)\'폭풍의 표식\'을 쌓으려 하니 미니언 뒤에 숨어 피해를 최소화하세요. (Q)\'부식성 폭약\'을 맞춰 케넨을 둔화시키면 평타 딜교환을 시도하기 편해요. 표식이 쌓이기 전에 거리를 조절하며 파밍에 집중하세요.', lv3: '케넨이 (E)\'번개 질주\'로 접근하며 표식을 쌓으려 하면 (E)\'경멸\'을 사용하여 케넨을 기절시키고 거리를 만드세요. (W)\'전류 방출\'에 맞으면 표식이 빠르게 쌓이니 케넨의 스킬이 빠진 것을 확인하고 (W)\'심판의 원\'으로 딜교환을 하세요. (Q)\'부식성 폭약\'으로 둔화를 걸어 전투를 시작하면 좋아요.', lv6: '케넨이 (R)\'날카로운 소용돌이\'를 사용하면 방어력과 마법 저항력이 올라가니 무리하게 붙지 마세요. 케넨의 체력이 낮아졌을 때 (R)\'불사의 공포\'를 맞히면 처형까지 노릴 수 있어요. 케넨이 궁극기를 사용한 직후에는 한타가 벌어질 수 있으니 라인 관리에 유의하세요.', item: '굶주린 히드라를 첫 코어로 가서 라인 유지력을 높이세요. 신발은 케넨의 마법 피해와 기절 지속 시간을 줄이는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 유체화를 추천해요. 유체화로 (E)\'번개 질주\'를 사용해 거리를 벌리는 케넨에게 빠르게 붙으세요.' },
    '케일': { lv1: '케일은 (P)\'거룩한 승천\'으로 레벨이 오를수록 강해지기 때문에 초반이 가장 약한 구간이에요. (Q)\'광휘의 일격\'의 사거리가 길어 견제받을 수 있으니 주의하며 (Q)\'부식성 폭약\'으로 둔화를 걸고 압박하세요.', lv3: '케일이 (W)\'천상의 축복\'으로 체력을 회복하며 도망가지 못하게 (E)\'경멸\'을 사용하여 적을 뒤로 던지세요. 케일의 (Q)\'광휘의 일격\'이 빠진 것을 확인하고 진입해야 방어력 감소와 둔화 피해를 피할 수 있어요.', lv6: '케일의 (R)\'신성한 심판\'은 아군을 무적 상태로 만드니 궁극기가 있는지 확인하고 (R)\'불사의 공포\'를 사용하세요. 케일의 체력이 낮아졌을 때 (E)\'경멸\'로 기절을 시킨 뒤 확실하게 처형을 노리는 것이 좋아요. 라인을 당기며 정글러의 개입을 유도해 보세요.', item: '헤르메스의 발걸음을 구매해 케일의 마법 피해에 대비하세요. 갈라진 하늘을 첫 코어로 가서 전투 지속력을 높이는 것이 좋아요.', spell: '점멸과 점화를 추천해요. 초반에 점화로 케일의 체력을 깎아 성장을 늦추는 것이 중요해요.' },
    '코그모': { lv1: '1~2레벨에는 코그모의 (Q)\'부식성 침\' 사거리에 노출되어 피해를 입기 쉬워요. (Q)\'부식성 폭약\'을 적중시켜 둔화를 걸며 거리를 좁힐 준비를 하세요. 미니언을 챙기며 코그모의 견제를 최대한 버티는 것이 중요해요.', lv3: '3레벨이 되면 (E)\'경멸\'로 돌진하여 코그모를 기절시킨 뒤 (W)\'심판의 원\'으로 딜교환을 하세요. 코그모가 (W)\'생체마법 폭격\'을 사용해 사거리를 늘린 상태라면 신중하게 진입해야 해요. (Q)\'부식성 폭약\'을 먼저 맞춰 이동 속도를 줄이는 것이 효율적이에요.', lv6: '(R)\'불사의 공포\'가 생기면 체력이 낮은 코그모를 직접 처형할 기회가 생겨요. (E)\'경멸\'로 접근한 뒤 체력이 낮은 적에게 (R)\'불사의 공포\'를 사용하세요. 코그모의 (R)\'살아있는 곡사포\' 범위 안에서 체력이 너무 낮아지지 않게 조심하며 정글러를 불러요.', item: '헤르메스의 발걸음과 갈라진 하늘을 가세요. 코그모의 마법 피해를 견디기 위해 헤르메스의 발걸음을 사고, 전투 지속력을 위해 갈라진 하늘을 선택해요.', spell: '점멸과 점화. 코그모에게 빠르게 접근하고 처형을 돕기 위해 사용해요.' },
    '코르키': { lv1: '(Q)\'인광탄\'의 사거리가 길기 때문에 초반 웨이브에서는 경험치만 챙기며 뒤로 물러나세요. (Q)\'부식성 폭약\'을 던져 상대의 접근을 둔화시키고 피해를 최소화하며 버티는 것이 중요해요.', lv3: '(Q)\'부식성 폭약\'을 맞힌 뒤 (W)\'심판의 원\'으로 빠르게 피해를 입히세요. 상대가 (W)\'발키리\'로 도망가기 전에 (E)\'경멸\'로 낚아채 뒤로 넘겨야 딜교환에서 앞설 수 있어요. (E)\'개틀링 건\'에 맞으면 방어력이 낮아지니 주의하세요.', lv6: '(R)\'불사의 공포\'를 맞혀 둔화시킨 후 체력이 낮아지면 재사용해 끌어당겨 처형 각을 보세요. 상대의 (R)\'미사일 폭격\'은 사거리가 매우 길어서 무빙으로 피하며 거리를 좁혀야 해요. 라인을 당겨 정글의 도움을 받거나 (E)\'경멸\'로 갑작스럽게 진입하세요.', item: '헤르메스의 발걸음과 삼위일체를 가세요. 마법 저항력으로 (Q)\'인광탄\' 피해를 줄이고 공격력과 체력을 높여 맞딜을 보강해요.', spell: '점멸과 순간이동을 추천해요. (E)\'경멸\'과 함께 사용하여 킬각을 잡고 순간이동으로 라인 복귀를 빠르게 하세요.' },
    '퀸': { lv1: '퀸은 (P)\'매사냥\' 표식을 활용한 평타 견제가 매우 강하니 첫 웨이브에서는 무리하지 말고 경험치 위주로 받으세요. (Q)\'실명 공격\'에 맞으면 시야가 좁아지니 주의하고, 퀸이 (E)\'공중제비\'로 진입했다가 물러나면 (Q)\'부식성 폭약\'을 발사해 둔화를 거세요. 최대한 맞딜을 피하며 체력을 보존하는 것이 중요해요.', lv3: '퀸이 (E)\'공중제비\'를 사용하여 거리를 벌리려 할 때 (E)\'경멸\'로 돌진해 뒤로 던지세요. (Q)\'부식성 폭약\'을 먼저 맞혀 둔화를 걸면 (E)\'경멸\' 적중률을 높일 수 있고, 이후 (W)\'심판의 원\'으로 빠르게 피해를 입히세요. 퀸의 (Q)\'실명 공격\'이 빠진 타이밍을 노려 과감하게 진입하세요.', lv6: '(R)\'불사의 공포\'를 맞히면 퀸의 낮은 체력을 이용해 처형 각을 잡으세요. 퀸이 (R)\'후방 지원\'을 켜고 빠르게 움직이며 견제할 때는 (Q)\'부식성 폭약\'을 맞혀 둔화를 거세요. 퀸이 로밍을 시도하면 즉시 라인을 밀어 넣고 아군 정글러에게 알려 대처하세요.', item: '삼위일체를 첫 코어로 선택해 공격력과 체력을 보충하고 맞딜 능력을 높이세요. 신발은 퀸의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 순간이동을 추천해요. 퀸의 강력한 기동성으로 인한 로밍에 빠르게 대응하기 위해서예요.' },
    '크산테': { lv1: '크산테는 (Q)\'엔토포 타격\'으로 둔화를 걸며 견제해요. 우르곳은 (Q)\'부식성 폭약\'을 적중시켜 둔화를 걸며 맞대응하세요. 크산테가 (Q)\'엔토포 타격\' 중첩을 쌓아 충격파로 끌어당기지 못하게 거리 조절을 하세요.', lv3: '크산테가 (W)\'길을 여는 자\'로 충전하는 모습이 보이면 저지 불가 돌진은 군중 제어로 막을 수 없으니 미리 옆으로 거리를 벌리세요. 돌진이 빠진 뒤에 (E)\'경멸\'로 진입하세요. 크산테의 (E)\'발놀림\' 보호막이 빠진 시점에 (W)\'심판의 원\'을 사용하여 딜교환을 하세요.', lv6: '크산테가 (R)\'총공세\'를 쓰면 방어력이 감소하는 대신 피해량이 늘어나니 정면 교환은 피하세요. 크산테가 벽을 넘겨 멀리 보낼 수 있으니 (R)\'불사의 공포\'를 사용할 위치를 잘 잡아야 해요. 크산테의 궁극기가 빠진 뒤에는 (R)\'불사의 공포\'로 체력이 낮은 상대를 처형하며 킬을 노리세요.', item: '크산테의 기본 공격 피해에 대비해 판금 장화를 선택하고 첫 코어로 칠흑의 양날 도끼를 가세요. 칠흑의 양날 도끼는 단단한 크산테의 방어력을 깎아줘요.', spell: '점멸과 점화를 추천해요. 크산테의 체력이 낮아졌을 때 (R)\'불사의 공포\'와 함께 사용하여 마무리 피해를 입히세요.' },
    '클레드': { lv1: '1~2레벨에는 (Q)\'부식성 폭약\'을 던져 스칼의 체력을 깎으며 견제하세요. 클레드의 (Q)\'덫날리기\'에 붙잡히면 끌려가며 추가 피해를 입으니 맞았을 때 즉시 거리를 벌리세요. 스칼에서 내린 클레드는 챔피언 피해량이 줄어드니 그때 평타로 압박하세요.', lv3: '(E)\'이랴!\'로 돌진하는 클레드를 (E)\'경멸\'로 쳐내어 뒤로 던진 뒤 (W)\'심판의 원\'으로 빠르게 피해를 입히세요. 클레드가 (W)\'버럭버럭\'을 켜고 빠른 공격을 퍼부을 때는 무리하게 싸우지 말고 거리를 유지하세요. (Q)\'부식성 폭약\'으로 둔화를 먼저 걸어야 (W)\'심판의 원\'의 표식을 남겨 효율적으로 공격할 수 있어요.', lv6: '(R)\'돌겨어어억!!!\'은 일직선으로 돌진하며 보호막을 얻으니 옆으로 움직여 피하고 적절한 타이밍에 (R)\'불사의 공포\'를 맞히세요. 스칼에서 내린 클레드는 체력이 낮으므로 (R)\'불사의 공포\'의 처형 범위에 빠르게 들어와 정리를 하기 편해요. 라인을 당겨서 적 정글의 개입을 줄이고 클레드가 스칼을 다시 타기 전에 처치하세요.', item: '삼위일체를 첫 코어로 선택해 체력과 공격력을 챙기고 빠른 공격으로 대응하세요. 신발은 클레드의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화의 강력한 피해를 더해 클레드가 스칼을 다시 타기 전에 빠르게 처치하세요.' },
    '탐켄치': { lv1: '탐 켄치는 (Q)\'혀 채찍\'으로 견제하며 체력을 회복하니 미니언 뒤에서 대기하며 (P)\'절대 미각\' 중첩이 쌓이지 않게 주의하세요. (Q)\'부식성 폭약\'을 맞춰 탐 켄치를 둔화시킨 뒤 (W)\'심판의 원\'으로 짧게 딜교환을 하고 빠지는 것이 좋아요.', lv3: '탐 켄치가 (E)\'두꺼운 피부\'를 사용해 보호막을 생성하면 딜을 멈추고 기다리세요. (E)\'경멸\'로 탐 켄치를 적중시켜 기절시킨 뒤 (W)\'심판의 원\'으로 화력을 집중하면 효율적이에요. (Q)\'혀 채찍\'에 맞아 기절하지 않도록 중첩 관리를 철저히 하세요.', lv6: '탐 켄치의 (R)\'집어삼키기\'로 먹히지 않도록 (P)\'절대 미각\' 중첩이 쌓였을 때는 거리를 두세요. 체력이 낮은 탐 켄치에게 (R)\'불사의 공포\'를 맞히면 처형까지 노릴 수 있어 킬각을 잡기 좋아요. (E)\'경멸\'의 보호막을 활용해 탐 켄치의 스킬을 버티며 라인을 관리하세요.', item: '첫 코어로 삼위일체를 가서 전투 지속력을 높이세요. 신발은 탐 켄치의 마법 피해를 줄이기 위해 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 탐 켄치의 체력 회복 효과를 감소시키며 킬을 노리세요.' },
    '트런들': { lv1: '트런들은 (Q)\'깨물기\'로 공격력을 훔치며 초반 싸움이 강해요. 1~2레벨에는 (Q)\'부식성 폭약\'을 사용하여 트런들의 접근을 늦추며 거리를 유지하세요. 트런들은 (P)\'헌납\'으로 주변 유닛이 쓰러질 때 회복하니 미니언이 많은 곳에서 싸움을 피하세요.', lv3: '트런들의 (W)\'얼음 왕국\' 영역 안에서는 공격 속도와 치유량이 늘어나니 밖에서 싸우세요. (E)\'경멸\'로 트런들을 뒤로 던지거나 거리를 벌리며 (Q)\'부식성 폭약\'을 맞히는 것이 중요해요. 트런들의 (Q)\'깨물기\'를 피한 뒤에 (Q)\'부식성 폭약\'으로 둔화시키고 (W)\'심판의 원\'을 사용하세요.', lv6: '트런들이 (R)\'진압\'으로 체력과 방어력을 훔치면 매우 강력하니 주의해야 해요. (R)\'불사의 공포\'로 처형을 노리되 (E)\'얼음 기둥\' 때문에 거리가 벌어지지 않게 조심하세요. 트런들이 (W)\'얼음 왕국\' 안에서 (P)\'헌납\'으로 버틸 수 있으니 정글러를 불러 함께 처치하세요.', item: '첫 코어로 칠흑의 양날 도끼를 가고 신발은 판금 장화를 신으세요. 트런들의 기본 공격 피해를 줄이기 위해 판금 장화가 필요하고 칠흑의 양날 도끼는 방어력을 깎는 데 유용해요.', spell: '점멸과 점화를 추천해요. 트런들이 (P)\'헌납\'으로 회복하는 양을 점화로 줄여서 마무리하세요.' },
    '트린다미어': { lv1: '트린다미어는 (P)\'격노\'를 쌓아 치명타를 노리며 강하게 압박해요. (Q)\'부식성 폭약\'을 먼저 맞혀 둔화시킨 뒤 평타로 견제하며 거리를 유지하세요. (E)\'회전 베기\'로 진입할 때 너무 깊게 들어오지 않도록 미니언 뒤에서 조심스럽게 대응해요.', lv3: '(E)\'회전 베기\'로 들어오는 순간을 기다렸다가 (E)\'경멸\'로 튕겨내어 기절시키세요. 적이 내 뒤로 넘어왔을 때 (W)\'심판의 원\'을 켜서 빠르게 피해를 입히는 것이 중요해요. (W)\'조롱의 외침\'에 걸려 등을 돌리면 둔화되니 정면에서 맞서며 딜교환을 하세요.', lv6: '(R)\'불사의 분노\'가 켜진 동안에는 트린다미어의 체력이 일정 수준 아래로 내려가지 않으니 (R)\'불사의 공포\'로 처치하지 못할 수 있어요. 지속시간이 끝난 뒤에 (R)\'불사의 공포\'로 마무리하는 것이 가장 확실해요. 정글러가 올 때는 (E)\'경멸\'로 트린다미어를 뒤로 던져 아군이 딜을 넣을 공간을 만들어주세요.', item: '삼위일체와 판금 장화를 추천해요. 삼위일체로 공격력과 체력을 챙기고, 판금 장화의 기본 공격 피해 감소 효과로 트린다미어의 치명타 피해를 줄이세요.', spell: '점멸과 점화를 추천해요. 트린다미어가 (Q)\'피의 갈망\'으로 체력을 회복하는 것을 점화의 치유 감소 효과로 억제하세요.' },
    '티모': { lv1: '티모는 (E)\'맹독 다트\'를 통해 평타마다 지속적인 피해를 입히고 (Q)\'실명 다트\'로 공격을 방해해요. 1~2레벨 구간에는 (Q)\'부식성 폭약\'으로 티모의 이동 속도를 늦추며 미니언을 챙기세요. 티모의 (Q)\'실명 다트\'를 맞으면 평타 교환을 멈추고 거리를 유지해야 해요.', lv3: '티모가 (W)\'신속한 이동\'으로 거리를 벌리려 할 때 (E)\'경멸\'을 사용해 돌진하며 기절을 노려야 해요. 티모의 (Q)\'실명 다트\'가 빠진 것을 확인한 뒤에 (W)\'심판의 원\'을 켜고 거리를 좁히세요. (Q)\'부식성 폭약\'으로 둔화를 먼저 걸면 (E)\'경멸\'을 맞히기가 훨씬 쉬워져요.', lv6: '티모의 (R)\'유독성 함정\'은 밟으면 둔화와 피해를 입히니 길목에 깔린 버섯을 조심하며 움직이세요. 티모의 체력이 낮아지면 (R)\'불사의 공포\'로 적을 끌어당겨 처형할 수 있어요. (E)\'경멸\'로 진입한 뒤 티모의 체력을 깎아 (R)\'불사의 공포\'로 확실하게 마무리하세요.', item: '헤르메스의 발걸음을 신발로 선택해 티모의 마법 피해에 대비하세요. 첫 코어 아이템은 갈라진 하늘을 가서 전투 지속력을 높여요.', spell: '점멸과 점화를 추천해요. 티모가 (W)\'신속한 이동\'으로 도망치려 할 때 점화로 마무리 피해를 입히며 킬을 노릴 수 있어요.' },
    '판테온': { lv1: '판테온은 (Q)\'혜성의 창\'을 던져 견제하며 초반에 강한 압박을 넣어요. (Q)\'부식성 폭약\'을 적중시켜 둔화를 걸고 거리 조절을 하며 경험치만 챙기세요. (P)\'필멸자의 의지\'가 활성화된 상태에서는 피해량이 높으니 가급적 교환을 피하는 게 좋아요.', lv3: '판테온이 (W)\'방호의 도약\'으로 진입해 기절시키려 하면 (E)\'경멸\'을 사용해 뒤로 던져 거리 조절을 하세요. (E)\'방패 돌격\'을 사용하면 정면의 피해를 모두 무시하니 (W)\'심판의 원\' 사격이 낭비되지 않게 방패가 끝난 뒤에 사용하세요. 먼저 (Q)\'부식성 폭약\'으로 둔화를 걸고 표식을 남긴 뒤 사격하는 구도를 만드세요.', lv6: '판테온이 (R)\'거대 유성\'으로 날아와 진입하면 빠르게 (Q)\'부식성 폭약\'을 써서 둔화를 걸어 거리 조절을 하세요. 상대 체력이 낮아졌을 때 (R)\'불사의 공포\'를 맞춰 제압하고 처형하면 순식간에 킬을 낼 수 있어요. (R)\'거대 유성\'을 이용한 빠른 합류가 가능하니 라인을 너무 깊게 밀지 말고 아군 정글러와 함께 움직이세요.', item: '삼위일체와 판금 장화를 추천해요. 삼위일체로 공격력과 체력을 보충하고 판금 장화의 효과로 판테온의 기본 공격 피해를 줄이세요.', spell: '점멸과 순간이동을 추천해요. 판테온의 (R)\'거대 유성\'을 이용한 빠른 합류에 대응해 빠르게 복귀하거나 합류하세요.' },
    '피들스틱': { lv1: '(Q)\'부식성 폭약\'을 사용하여 미니언과 함께 적을 견제하며 거리를 조절하세요. 피들스틱이 시야 밖에서 (Q)\'공포\'를 사용하여 갑작스럽게 달려드는 것을 조심하며 파밍에 집중해요.', lv3: '피들스틱이 (W)\'풍작\'을 사용하여 체력을 회복할 때 (E)\'경멸\'로 흐름을 끊어주세요. (Q)\'부식성 폭약\'으로 적을 둔화시킨 뒤 (W)\'심판의 원\'을 사용하여 피해를 입히면 좋아요. (E)\'수확\'의 중심부에 맞으면 침묵에 걸리니 주의하세요.', lv6: '피들스틱이 (R)\'까마귀 폭풍\'을 사용하여 진입할 때 (E)\'경멸\'로 대응하여 차단하세요. 상대 체력이 낮을 때 (R)\'불사의 공포\'를 사용하여 확실하게 처치하는 것이 좋아요. 라인을 적절히 관리하며 정글러의 개입에 대비하세요.', item: '헤르메스의 발걸음과 맬모셔스의 아귀예요. 마법 저항력을 확보하고 생명선을 통해 생존력을 높여요.', spell: '점멸과 점화예요. 점멸로 (E)\'경멸\'을 맞히기 쉬운 거리를 만들고 점화로 적의 체력을 빠르게 깎아요.' },
    '피오라': { lv1: '피오라는 (Q)\'찌르기\'로 돌진하며 (P)\'치명적인 검무\' 급소를 가격해 체력을 회복하고 빠르게 움직여요. (Q)\'부식성 폭약\'을 맞춰 둔화시키며 거리를 유지하고, 급소 방향을 계속 틀어 피오라가 쉽게 가격하지 못하게 하세요. 초반에는 무리하게 붙기보다 원거리에서 견제하며 피해를 최소화해요.', lv3: '피오라가 (W)\'응수\'를 쓰면 (E)\'경멸\'의 기절 효과가 막히고 오히려 기절당하니, (W)\'응수\'가 빠진 것을 확인하고 돌진하세요. (Q)\'부식성 폭약\'으로 둔화를 건 뒤 (W)\'심판의 원\'을 켜서 빠르게 피해를 입히는 것이 중요해요. (E)\'대가의 검술\'의 치명타 평타를 맞기 전에 스킬을 사용해 빠르게 거리를 조절하세요.', lv6: '피오라가 (R)\'대결투\'를 사용하면 급소가 네 군데 드러나므로, 최대한 뒤로 빠지며 급소를 내주지 마세요. (R)\'불사의 공포\'를 맞춰 둔화시킨 뒤, 체력이 낮아졌을 때 제압하여 처형하고 주변에 공포를 거세요. (W)\'응수\'로 궁극기 투사체가 막히지 않도록 타이밍을 잘 계산해서 사용하세요.', item: '삼위일체를 첫 코어로 가서 공격력과 체력 그리고 공격 속도를 챙겨 지속 교전 능력을 높이세요. 신발은 피오라의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 피오라는 (P)\'치명적인 검무\'와 (R)\'대결투\'로 체력을 많이 회복하므로 점화의 치유 감소 효과가 필수적이에요.' },
    '하이머딩거': { lv1: '하이머딩거는 (Q)\'H-28 G 진화형 포탑\'을 설치해 라인 근처를 장악하려 해요. 포탑 사거리 안에서 미니언을 치면 피해가 크니, 포탑의 공격 사선을 피해 (Q)\'부식성 폭약\'으로 멀리서 견제하며 버티세요. 포탑이 설치된 곳을 피해 막타를 챙기는 것이 중요해요.', lv3: '하이머딩거가 (E)\'CH-2 전자폭풍 수류탄\'을 던지면 기절에 걸릴 수 있으니 위치를 잘 잡으세요. 수류탄이 빗나간 뒤에 (E)\'경멸\'로 돌진하여 하이머딩거를 뒤로 던지고, (Q)\'부식성 폭약\'의 둔화 효과를 이용해 (W)\'심판의 원\'으로 압박하세요. 포탑의 공격을 받지 않는 위치에서 싸우는 것이 핵심이에요.', lv6: '하이머딩거가 (R)\'업그레이드!!!\'를 사용해 강화된 스킬을 쓰면 피해가 매우 크니 주의해야 해요. 하이머딩거의 체력이 낮을 때 (R)\'불사의 공포\'를 사용하여 마무리할 수 있지만, 포탑과 로켓 피해를 조심하며 진입하세요. 포탑을 빠르게 정리하며 라인을 관리하고 정글러의 개입을 유도하세요.', item: '삼위일체를 첫 코어로 가서 전투 지속력을 높이세요. 신발은 하이머딩거의 마법 피해와 기절 지속 시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 하이머딩거의 체력이 낮을 때 점화로 빠르게 마무리하여 (R)\'불사의 공포\'를 활용하세요.' }
  }
};
// 사이트 등록: window.TOP_MATCHUPS['내챔피언_상대'] = { lvl1, lvl3, lvl6, item, spell } (이름의 띄어쓰기는 제거)
(function (d) {
  var g = typeof window !== 'undefined' ? window : globalThis;
  g.TOP_MATCHUPS = g.TOP_MATCHUPS || {};
  var me = d.champion.replace(/\s+/g, '');
  Object.keys(d.matchups).forEach(function (opp) {
    var m = d.matchups[opp];
    g.TOP_MATCHUPS[me + '_' + opp.replace(/\s+/g, '')] = { lvl1: m.lv1, lvl3: m.lv3, lvl6: m.lv6, item: m.item, spell: m.spell };
  });
})(top_urgot);
if (typeof module !== 'undefined') module.exports = top_urgot;
